def resolve(path, role):
    try:
        proc = subprocess.run([b"/usr/bin/readlink", b"-f", b"--", path],
                              stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:
        error(role + ":resolve-failed")
