    b"usersubstr": "int", b"enforcing": "int", b"badwords": "str", b"dictpath": "str",
    b"retry": "int", b"enforce_for_root": "set", b"local_users_only": "set",
}
DEFAULTS = {"minlen": 8, "dcredit": 0, "ucredit": 0, "lcredit": 0, "ocredit": 0, "retry": 1,
