    if kind == "int":
        number = _int(value, reason)
        if key in DEFAULTS:
            settings[key] = number
    elif key == "dictpath":
        settings[key] = value
    elif key == "enforce_for_root":
        # libpwquality set_name_value: настройка вида set включается при любом значении.
        settings[key] = True


