    for name in names:
        i = name.find(b".conf")
        if i >= 0 and name[i + 5:] == b"":
            chosen.append(name)
    return sorted(chosen)


def pam_module_args(raw):
    """Аргументы единственной действующей строки password … pam_pwquality.so или None."""
