    for arg in args:
        name, sep, rest = arg.partition(b"=")
        if name.lower() == key.encode("ascii"):
            if not sep:
                raise ParseError("pam:invalid-argument")
            value = _int(rest, "pam:invalid-argument")
    if key == "minlen" and value < 6:
        value = 6
    if key == "retry" and value < 1:
        value = 1
    return value


