    if b"\x00" in raw:
        raise ParseError("pwquality:invalid-bytes")
    lines = raw.split(b"\n")
    if raw.endswith(b"\n"):
        lines.pop()
    result = []
    for number, line in enumerate(lines):
        if len(line) > MAX_LINE:
            raise ParseError("pwquality:line-too-long")
        end = line.find(b"#")
        if end < 0:
            end = len(line)
        while end > 0 and line[end - 1] in C_SPACE:
            end -= 1
        start = 0
        while start < end and line[start] in C_SPACE:
            start += 1
        if start == end:
            continue
        pos = start
        while pos < end and line[pos] not in C_SPACE and line[pos] != 61:
            pos += 1
        name = line[start:pos]
        eq = False
        if pos < end:
            eq = line[pos] == 61
            pos += 1
        while pos < end:
            c = line[pos]
            if c != 61 or eq:
                if c not in C_SPACE:
                    break
            else:
                eq = True
            pos += 1
        result.append((number, name, pos, end))
    return result


