slp_pretty_status() {
  case "$1" in
    PASS) printf '%s' ok ;;
    FAIL) printf '%s' fail ;;
    ERROR) printf '%s' err ;;
    NOT_FOUND) printf '%s' nf ;;
    NOT_APPLICABLE) printf '%s' na ;;
    *) return 1 ;;
  esac
}

SLP_PRETTY_COLS=116
SLP_PRETTY_MODE=table
SLP_PRETTY_WS=5
SLP_PRETTY_WSRC=29
SLP_PRETTY_WC=29
SLP_PRETTY_WCUR=14
SLP_PRETTY_WREQ=24
SLP_PRETTY_VFIELD=8
SLP_PRETTY_VVALUE=104

slp_terminal_columns() {
  local _slp_size='' _slp_rows='' _slp_cols='' _slp_extra=''
  if [[ -r /dev/tty && -x /usr/bin/stty ]]; then
    _slp_size=$(command /usr/bin/stty size < /dev/tty 2>/dev/null) || _slp_size=''
    if [[ -n $_slp_size ]]; then
      read -r _slp_rows _slp_cols _slp_extra <<< "$_slp_size"
      if [[ $_slp_rows =~ ^[0-9]+$ && $_slp_cols =~ ^[0-9]+$ && -z $_slp_extra ]] && (( _slp_cols >= 40 && _slp_cols <= 1000 )); then
        printf '%s\n' "$_slp_cols"
        return 0
      fi
    fi
  fi
  printf '116\n'
}

slp_pretty_layout_for_cols() {
  local _slp_cols=$1 _slp_available _slp_remaining _slp_req_min
  [[ $_slp_cols =~ ^[0-9]+$ ]] || return 1
  (( _slp_cols >= 40 && _slp_cols <= 1000 )) || return 1
  SLP_PRETTY_COLS=$_slp_cols
  SLP_PRETTY_WS=5
  if (( _slp_cols < 90 )); then
    SLP_PRETTY_MODE=vertical
    SLP_PRETTY_VFIELD=8
    SLP_PRETTY_VVALUE=$((_slp_cols - SLP_PRETTY_VFIELD - 6))
    (( SLP_PRETTY_VVALUE > 0 )) || return 1
    return 0
  fi
  SLP_PRETTY_MODE=table
  if (( _slp_cols < 100 )); then
    SLP_PRETTY_WSRC=18
    SLP_PRETTY_WC=24
    _slp_req_min=10
  elif (( _slp_cols < 110 )); then
    SLP_PRETTY_WSRC=30
    SLP_PRETTY_WC=24
    _slp_req_min=12
  elif (( _slp_cols < 120 )); then
    SLP_PRETTY_WSRC=30
    SLP_PRETTY_WC=28
    _slp_req_min=14
  else
    SLP_PRETTY_WSRC=30
    SLP_PRETTY_WC=32
    _slp_req_min=16
  fi
  _slp_available=$((_slp_cols - 15))
  _slp_remaining=$((_slp_available - SLP_PRETTY_WS - SLP_PRETTY_WSRC - SLP_PRETTY_WC))
  (( _slp_remaining > _slp_req_min )) || return 1
  SLP_PRETTY_WCUR=$((_slp_remaining - _slp_req_min))
  (( SLP_PRETTY_WCUR > 43 )) && SLP_PRETTY_WCUR=43
  # current отдаёт required 10 символов, но не становится уже 12.
  if (( SLP_PRETTY_WCUR - 10 > 12 )); then
    SLP_PRETTY_WCUR=$((SLP_PRETTY_WCUR - 10))
  elif (( SLP_PRETTY_WCUR > 12 )); then
    SLP_PRETTY_WCUR=12
  fi
  SLP_PRETTY_WREQ=$((_slp_remaining - SLP_PRETTY_WCUR))
}

slp_pretty_layout_init() {
  local _slp_cols
  if [[ ! -t 1 ]]; then
    slp_pretty_layout_for_cols 116
    return $?
  fi
  _slp_cols=$(slp_terminal_columns) || return 1
  slp_pretty_layout_for_cols "$_slp_cols"
}

slp_repeat_dash() {
  local _slp_n=$1 _slp_out
  printf -v _slp_out '%*s' "$_slp_n" ''
  printf '%s' "${_slp_out// /-}"
}

slp_pretty_separator() {
  if [[ $SLP_PRETTY_MODE == vertical ]]; then
    slp_repeat_dash $((SLP_PRETTY_VFIELD + 2))
    printf '+'
    slp_repeat_dash $((SLP_PRETTY_VVALUE + 2))
    printf '+\n'
    return 0
  fi
  slp_repeat_dash $((SLP_PRETTY_WS + 2))
  printf '+'
  slp_repeat_dash $((SLP_PRETTY_WSRC + 2))
  printf '+'
  slp_repeat_dash $((SLP_PRETTY_WC + 2))
  printf '+'
  slp_repeat_dash $((SLP_PRETTY_WCUR + 2))
  printf '+'
  slp_repeat_dash $((SLP_PRETTY_WREQ + 2))
  printf '+\n'
}

slp_pretty_cell() {
  local _slp_text=$1 _slp_width=$2 _slp_chars _slp_bytes _slp_printf_width
  local LC_ALL=C.UTF-8
  _slp_chars=${#_slp_text}
  LC_ALL=C
  _slp_bytes=${#_slp_text}
  _slp_printf_width=$((_slp_width + _slp_bytes - _slp_chars))
  printf '%-*s' "$_slp_printf_width" "$_slp_text"
}

slp_pretty_vertical_field() {
  local LC_ALL=C.UTF-8
  local _slp_label=$1 _slp_text=$2 _slp_chunk
  if [[ -z $_slp_text ]]; then
    printf ' '
    slp_pretty_cell "$_slp_label" "$SLP_PRETTY_VFIELD"
    printf ' | '
    slp_pretty_cell '' "$SLP_PRETTY_VVALUE"
    printf ' |\n'
    return 0
  fi
  while [[ -n $_slp_text ]]; do
    _slp_chunk=${_slp_text:0:SLP_PRETTY_VVALUE}
    _slp_text=${_slp_text:SLP_PRETTY_VVALUE}
    printf ' '
    slp_pretty_cell "$_slp_label" "$SLP_PRETTY_VFIELD"
    printf ' | '
    slp_pretty_cell "$_slp_chunk" "$SLP_PRETTY_VVALUE"
    printf ' |\n'
    _slp_label=''
  done
}

slp_pretty_row() {
  local LC_ALL=C.UTF-8
  local _slp_st=$1 _slp_source=$2 _slp_control=$3 _slp_current=$4 _slp_required=$5
  local _slp_a _slp_b _slp_c _slp_d _slp_e
  if [[ $SLP_PRETTY_MODE == vertical ]]; then
    if [[ $_slp_st == st && $_slp_source == source && $_slp_control == control ]]; then
      printf ' '
      slp_pretty_cell field "$SLP_PRETTY_VFIELD"
      printf ' | '
      slp_pretty_cell value "$SLP_PRETTY_VVALUE"
      printf ' |\n'
      return 0
    fi
    slp_pretty_vertical_field st "$_slp_st"
    slp_pretty_vertical_field source "$_slp_source"
    slp_pretty_vertical_field control "$_slp_control"
    slp_pretty_vertical_field current "$_slp_current"
    slp_pretty_vertical_field required "$_slp_required"
    return 0
  fi
  while [[ -n $_slp_st || -n $_slp_source || -n $_slp_control || -n $_slp_current || -n $_slp_required ]]; do
    _slp_a=${_slp_st:0:SLP_PRETTY_WS}; _slp_st=${_slp_st:SLP_PRETTY_WS}
    _slp_b=${_slp_source:0:SLP_PRETTY_WSRC}; _slp_source=${_slp_source:SLP_PRETTY_WSRC}
    _slp_c=${_slp_control:0:SLP_PRETTY_WC}; _slp_control=${_slp_control:SLP_PRETTY_WC}
    _slp_d=${_slp_current:0:SLP_PRETTY_WCUR}; _slp_current=${_slp_current:SLP_PRETTY_WCUR}
    _slp_e=${_slp_required:0:SLP_PRETTY_WREQ}; _slp_required=${_slp_required:SLP_PRETTY_WREQ}
    printf ' '
    slp_pretty_cell "$_slp_a" "$SLP_PRETTY_WS"
    printf ' | '
    slp_pretty_cell "$_slp_b" "$SLP_PRETTY_WSRC"
    printf ' | '
    slp_pretty_cell "$_slp_c" "$SLP_PRETTY_WC"
    printf ' | '
    slp_pretty_cell "$_slp_d" "$SLP_PRETTY_WCUR"
    printf ' | '
    slp_pretty_cell "$_slp_e" "$SLP_PRETTY_WREQ"
    printf ' |\n'
  done
}

slp_collect_policy() {
  # reason допускает необязательный третий сегмент-payload (путь, цель
  # readlink и т. п.): <domain>:<reason>[:<payload>]. Payload может содержать
  # любые байты, кроме control-байт (0x00-0x1F, 0x7F) — они ломают
  # табличный/TSV вывод. Локаль фиксируется явно: классификация [:cntrl:]
  # обязана быть побайтовой, не зависеть от окружения вызова.
  # Аргументы — control id: проверяются только они (CHECK контролей без APPLY после --apply).
  local LC_ALL=C
  local _slp_fn _slp_expected_cid _slp_line _slp_tag _slp_cid _slp_status _slp_value _slp_comp _slp_extra
  local _slp_i _slp_want _slp_bad _slp_record_errors=0 _slp_rest
  if [[ ${1:-} == --record-errors ]]; then
    _slp_record_errors=1
    shift
  fi
  local -a _slp_fns=('slp_check_FSTEC_LINUX_2022_2_1_1_LOCAL_ACCOUNT_PASSWORD_STATE' 'slp_check_FSTEC_LINUX_2022_2_1_2_SSH_ROOT_LOGIN' 'slp_check_FSTEC_LINUX_2022_2_2_1_SU_WHEEL_ACCESS' 'slp_check_FSTEC_LINUX_2022_2_2_2_SUDOERS_REVIEWED_POLICY' 'slp_check_FSTEC_LINUX_2022_2_3_1_GROUP_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_1_PASSWD_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_1_SHADOW_GO_RWX' 'slp_check_FSTEC_LINUX_2022_2_3_2_RUNNING_PROCESS_PATHS_WRITE_PROTECTION' 'slp_check_FSTEC_LINUX_2022_2_3_3_CRON_COMMAND_PATHS_WRITE_PROTECTION' 'slp_check_FSTEC_LINUX_2022_2_3_4_SUDO_ROOT_COMMAND_FILES_PROTECTION' 'slp_check_FSTEC_LINUX_2022_2_3_5_STARTUP_FILES_WRITE_PROTECTION' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRON_D' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRON_DAILY' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRON_HOURLY' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRON_MONTHLY' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRON_WEEKLY' 'slp_check_FSTEC_LINUX_2022_2_3_6_CRONTAB' 'slp_check_FSTEC_LINUX_2022_2_3_7_USER_CRON_FILES_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_8_STANDARD_SYSTEM_PATHS_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_9_SUID_SGID_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_10_HOME_SENSITIVE_FILES_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_11_DIR_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_11_HOME_DIRECTORIES_MODE' 'slp_check_FSTEC_LINUX_2022_2_3_11_HOME_MODE' 'slp_check_FSTEC_LINUX_2022_2_4_1_DMESG_RESTRICT' 'slp_check_FSTEC_LINUX_2022_2_4_2_KPTR_RESTRICT' 'slp_check_FSTEC_LINUX_2022_2_4_3_INIT_ON_ALLOC' 'slp_check_FSTEC_LINUX_2022_2_4_4_SLAB_NOMERGE' 'slp_check_FSTEC_LINUX_2022_2_4_5_IOMMU_FORCE' 'slp_check_FSTEC_LINUX_2022_2_4_5_IOMMU_PASSTHROUGH' 'slp_check_FSTEC_LINUX_2022_2_4_5_IOMMU_STRICT' 'slp_check_FSTEC_LINUX_2022_2_4_6_RANDOMIZE_KSTACK_OFFSET' 'slp_check_FSTEC_LINUX_2022_2_4_7_MITIGATIONS' 'slp_check_FSTEC_LINUX_2022_2_4_8_BPF_JIT_HARDEN' 'slp_check_FSTEC_LINUX_2022_2_5_1_VSYSCALL' 'slp_check_FSTEC_LINUX_2022_2_5_2_PERF_EVENT_PARANOID' 'slp_check_FSTEC_LINUX_2022_2_5_3_DEBUGFS' 'slp_check_FSTEC_LINUX_2022_2_5_4_KEXEC_LOAD_DISABLED' 'slp_check_FSTEC_LINUX_2022_2_5_5_MAX_USER_NAMESPACES' 'slp_check_FSTEC_LINUX_2022_2_5_6_UNPRIVILEGED_BPF_DISABLED' 'slp_check_FSTEC_LINUX_2022_2_5_7_UNPRIVILEGED_USERFAULTFD' 'slp_check_FSTEC_LINUX_2022_2_5_8_LDISC_AUTOLOAD' 'slp_check_FSTEC_LINUX_2022_2_5_9_TSX' 'slp_check_FSTEC_LINUX_2022_2_5_10_MMAP_MIN_ADDR' 'slp_check_FSTEC_LINUX_2022_2_5_11_RANDOMIZE_VA_SPACE' 'slp_check_FSTEC_LINUX_2022_2_6_1_PTRACE_SCOPE' 'slp_check_FSTEC_LINUX_2022_2_6_2_PROTECTED_SYMLINKS' 'slp_check_FSTEC_LINUX_2022_2_6_3_PROTECTED_HARDLINKS' 'slp_check_FSTEC_LINUX_2022_2_6_4_PROTECTED_FIFOS' 'slp_check_FSTEC_LINUX_2022_2_6_5_PROTECTED_REGULAR' 'slp_check_FSTEC_LINUX_2022_2_6_6_SUID_DUMPABLE' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_1_AUDITD_PACKAGE' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_2_AUDITD_SERVICE' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_ADMIN_SPACE_LEFT_ACTION' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_DISK_FULL_ACTION' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_LOG_FILE' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_LOG_FORMAT' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_LOG_GROUP' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_MAX_LOG_FILE' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_MAX_LOG_FILE_ACTION' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_NUM_LOGS' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_3_SPACE_LEFT_ACTION' 'slp_check_FSTEC_LOGGING_2025_APPENDIX2_LINUX_4_AUDIT_RULES' 'slp_check_FSTEC_LOGGING_2025_MAIN_5_AUDIT_LOG_FREE_SPACE' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_ENCRYPT_METHOD' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_EXISTING_PASSWORD_AGE' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_EXISTING_PASSWORD_AGING' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PASS_MAX_DAYS' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PASS_MIN_DAYS' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PASS_WARN_AGE' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_DCREDIT' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_ENFORCE_FOR_ROOT' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_LCREDIT' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_MINLEN' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_OCREDIT' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_RETRY' 'slp_check_FSTEC_CONFIGURATION_2026_1_1_PWQUALITY_UCREDIT' 'slp_check_FSTEC_CONFIGURATION_2026_1_2_PWHISTORY_ENFORCE_FOR_ROOT' 'slp_check_FSTEC_CONFIGURATION_2026_1_2_PWHISTORY_REMEMBER' 'slp_check_FSTEC_CONFIGURATION_2026_8_4_SSH_LOG_LEVEL' 'slp_check_FSTEC_CONFIGURATION_2026_9_1_SSH_PASSWORD_AUTHENTICATION' 'slp_check_FSTEC_CONFIGURATION_2026_9_1_SSH_PERMIT_EMPTY_PASSWORDS' 'slp_check_FSTEC_CONFIGURATION_2026_9_1_SSH_PERMIT_ROOT_LOGIN' 'slp_check_FSTEC_CONFIGURATION_2026_11_2_FTP' 'slp_check_FSTEC_CONFIGURATION_2026_11_2_SNMP' 'slp_check_FSTEC_CONFIGURATION_2026_11_2_TELNET')
  local -a _slp_ids=('FSTEC-LINUX-2022-2.1.1-LOCAL-ACCOUNT-PASSWORD-STATE' 'FSTEC-LINUX-2022-2.1.2-SSH-ROOT-LOGIN' 'FSTEC-LINUX-2022-2.2.1-SU-WHEEL-ACCESS' 'FSTEC-LINUX-2022-2.2.2-SUDOERS-REVIEWED-POLICY' 'FSTEC-LINUX-2022-2.3.1-GROUP-MODE' 'FSTEC-LINUX-2022-2.3.1-PASSWD-MODE' 'FSTEC-LINUX-2022-2.3.1-SHADOW-GO-RWX' 'FSTEC-LINUX-2022-2.3.2-RUNNING-PROCESS-PATHS-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.3-CRON-COMMAND-PATHS-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.4-SUDO-ROOT-COMMAND-FILES-PROTECTION' 'FSTEC-LINUX-2022-2.3.5-STARTUP-FILES-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.6-CRON-D' 'FSTEC-LINUX-2022-2.3.6-CRON-DAILY' 'FSTEC-LINUX-2022-2.3.6-CRON-HOURLY' 'FSTEC-LINUX-2022-2.3.6-CRON-MONTHLY' 'FSTEC-LINUX-2022-2.3.6-CRON-WEEKLY' 'FSTEC-LINUX-2022-2.3.6-CRONTAB' 'FSTEC-LINUX-2022-2.3.7-USER-CRON-FILES-MODE' 'FSTEC-LINUX-2022-2.3.8-STANDARD-SYSTEM-PATHS-MODE' 'FSTEC-LINUX-2022-2.3.9-SUID-SGID-MODE' 'FSTEC-LINUX-2022-2.3.10-HOME-SENSITIVE-FILES-MODE' 'FSTEC-LINUX-2022-2.3.11-DIR-MODE' 'FSTEC-LINUX-2022-2.3.11-HOME-DIRECTORIES-MODE' 'FSTEC-LINUX-2022-2.3.11-HOME-MODE' 'FSTEC-LINUX-2022-2.4.1-DMESG-RESTRICT' 'FSTEC-LINUX-2022-2.4.2-KPTR-RESTRICT' 'FSTEC-LINUX-2022-2.4.3-INIT-ON-ALLOC' 'FSTEC-LINUX-2022-2.4.4-SLAB-NOMERGE' 'FSTEC-LINUX-2022-2.4.5-IOMMU-FORCE' 'FSTEC-LINUX-2022-2.4.5-IOMMU-PASSTHROUGH' 'FSTEC-LINUX-2022-2.4.5-IOMMU-STRICT' 'FSTEC-LINUX-2022-2.4.6-RANDOMIZE-KSTACK-OFFSET' 'FSTEC-LINUX-2022-2.4.7-MITIGATIONS' 'FSTEC-LINUX-2022-2.4.8-BPF-JIT-HARDEN' 'FSTEC-LINUX-2022-2.5.1-VSYSCALL' 'FSTEC-LINUX-2022-2.5.2-PERF-EVENT-PARANOID' 'FSTEC-LINUX-2022-2.5.3-DEBUGFS' 'FSTEC-LINUX-2022-2.5.4-KEXEC-LOAD-DISABLED' 'FSTEC-LINUX-2022-2.5.5-MAX-USER-NAMESPACES' 'FSTEC-LINUX-2022-2.5.6-UNPRIVILEGED-BPF-DISABLED' 'FSTEC-LINUX-2022-2.5.7-UNPRIVILEGED-USERFAULTFD' 'FSTEC-LINUX-2022-2.5.8-LDISC-AUTOLOAD' 'FSTEC-LINUX-2022-2.5.9-TSX' 'FSTEC-LINUX-2022-2.5.10-MMAP-MIN-ADDR' 'FSTEC-LINUX-2022-2.5.11-RANDOMIZE-VA-SPACE' 'FSTEC-LINUX-2022-2.6.1-PTRACE-SCOPE' 'FSTEC-LINUX-2022-2.6.2-PROTECTED-SYMLINKS' 'FSTEC-LINUX-2022-2.6.3-PROTECTED-HARDLINKS' 'FSTEC-LINUX-2022-2.6.4-PROTECTED-FIFOS' 'FSTEC-LINUX-2022-2.6.5-PROTECTED-REGULAR' 'FSTEC-LINUX-2022-2.6.6-SUID-DUMPABLE' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-1-AUDITD-PACKAGE' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-2-AUDITD-SERVICE' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-ADMIN-SPACE-LEFT-ACTION' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-DISK-FULL-ACTION' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FILE' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FORMAT' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-GROUP' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE-ACTION' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-NUM-LOGS' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-SPACE-LEFT-ACTION' 'FSTEC-LOGGING-2025-APPENDIX2-LINUX-4-AUDIT-RULES' 'FSTEC-LOGGING-2025-MAIN-5-AUDIT-LOG-FREE-SPACE' 'FSTEC-CONFIGURATION-2026-1.1-ENCRYPT-METHOD' 'FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGE' 'FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGING' 'FSTEC-CONFIGURATION-2026-1.1-PASS-MAX-DAYS' 'FSTEC-CONFIGURATION-2026-1.1-PASS-MIN-DAYS' 'FSTEC-CONFIGURATION-2026-1.1-PASS-WARN-AGE' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-DCREDIT' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-ENFORCE-FOR-ROOT' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-LCREDIT' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-MINLEN' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-OCREDIT' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-RETRY' 'FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-UCREDIT' 'FSTEC-CONFIGURATION-2026-1.2-PWHISTORY-ENFORCE-FOR-ROOT' 'FSTEC-CONFIGURATION-2026-1.2-PWHISTORY-REMEMBER' 'FSTEC-CONFIGURATION-2026-8.4-SSH-LOG-LEVEL' 'FSTEC-CONFIGURATION-2026-9.1-SSH-PASSWORD-AUTHENTICATION' 'FSTEC-CONFIGURATION-2026-9.1-SSH-PERMIT-EMPTY-PASSWORDS' 'FSTEC-CONFIGURATION-2026-9.1-SSH-PERMIT-ROOT-LOGIN' 'FSTEC-CONFIGURATION-2026-11.2-FTP' 'FSTEC-CONFIGURATION-2026-11.2-SNMP' 'FSTEC-CONFIGURATION-2026-11.2-TELNET')
  local -A _slp_only=()
  for _slp_want in "$@"; do _slp_only[$_slp_want]=1; done

  SLP_RESULTS=()
  SLP_TOTAL=0 SLP_PASS=0 SLP_FAIL=0 SLP_NF=0 SLP_NA=0 SLP_ERR=0 SLP_POLICY_STATUS='' SLP_POLICY_RC=0

  for ((_slp_i=0; _slp_i<${#_slp_fns[@]}; _slp_i++)); do
    _slp_fn=${_slp_fns[$_slp_i]}
    _slp_expected_cid=${_slp_ids[$_slp_i]}
    if (( $# > 0 )) && [[ -z ${_slp_only[$_slp_expected_cid]+x} ]]; then
      continue
    fi
    _slp_bad=0
    _slp_tag='' _slp_cid='' _slp_status='' _slp_value='' _slp_comp='' _slp_extra=''
    if ! _slp_line="$($_slp_fn)"; then
      _slp_bad=1
    else
      if [[ $_slp_line == *$'\n'* ]]; then
        _slp_bad=1
      fi
      _slp_rest=${_slp_line//$'\t'/}
      if (( ${#_slp_line} - ${#_slp_rest} != 4 )); then
        _slp_bad=1
      fi
      IFS=$'\t' read -r _slp_tag _slp_cid _slp_status _slp_value _slp_comp _slp_extra <<< "$_slp_line"
      if [[ $_slp_tag != SLP-CHECK-V1 || $_slp_cid != "$_slp_expected_cid" || -n $_slp_extra ]]; then
        _slp_bad=1
      fi
      case "$_slp_status:$_slp_comp" in
        VALUE:PASS|VALUE:FAIL|NOT_FOUND:FAIL|NOT_FOUND:NOT_FOUND|NOT_APPLICABLE:NOT_APPLICABLE|ERROR:ERROR) ;;
        *) _slp_bad=1 ;;
      esac
      if [[ $_slp_bad == 0 && $_slp_comp == ERROR ]]; then
        if [[ ! $_slp_value =~ ^[a-z][a-z0-9-]*:[a-z][a-z0-9-]*(:[^[:cntrl:]]*)?$ ]]; then
          _slp_bad=1
        fi
      fi
    fi
    if [[ $_slp_bad == 1 ]]; then
      if [[ $_slp_record_errors != 1 ]]; then
        printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2
        return 1
      fi
      _slp_line="SLP-CHECK-V1"$'\t'"$_slp_expected_cid"$'\t'"ERROR"$'\t'"check:internal-error"$'\t'"ERROR"
      _slp_status=ERROR _slp_value=check:internal-error _slp_comp=ERROR
    fi
    SLP_RESULTS+=("$_slp_line")
    ((SLP_TOTAL+=1))
    case "$_slp_comp" in
      PASS) ((SLP_PASS+=1)) ;;
      FAIL) ((SLP_FAIL+=1)) ;;
      NOT_FOUND) ((SLP_NF+=1)) ;;
      NOT_APPLICABLE) ((SLP_NA+=1)) ;;
      ERROR) ((SLP_ERR+=1)) ;;
      *) return 1 ;;
    esac
  done

  if (( $# > 0 && SLP_TOTAL != ${#_slp_only[@]} )); then
    printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2
    return 1
  fi
  if (( SLP_NF > 0 || SLP_ERR > 0 )); then
    SLP_POLICY_STATUS=UNEVALUATED
    SLP_POLICY_RC=1
  elif (( SLP_FAIL > 0 )); then
    SLP_POLICY_STATUS=NONCOMPLIANT
    SLP_POLICY_RC=0
  else
    SLP_POLICY_STATUS=COMPLIANT
    SLP_POLICY_RC=0
  fi
  return 0
}

slp_selected() {
  local _slp_result=$1 _slp_failed_only=$2
  if (( _slp_failed_only == 0 )); then return 0; fi
  [[ $_slp_result == FAIL || $_slp_result == ERROR ]]
}

slp_support_class() {
  if [[ $SLP_SYSTEM_TYPE == DESKTOP ]]; then
    printf '%s' FIELD_COMPATIBILITY
  else
    printf '%s' SUPPORTED
  fi
}

slp_render_raw() {
  local _slp_failed_only=$1 _slp_line _slp_tag _slp_cid _slp_status _slp_value _slp_comp
  printf 'SLP-PLATFORM-V1\tSYSTEM=%s\tID=%s\tVERSION_ID=%s\tARCH=%s\tPROFILE=%s\tTYPE=%s\tPLATFORM=%s\tENVIRONMENT=%s\tSUPPORT=%s\n' \
    "$SLP_SYSTEM_PRETTY_NAME" "$SLP_SYSTEM_ID" "$SLP_SYSTEM_VERSION_ID" "$SLP_SYSTEM_ARCH" \
    "$SLP_SYSTEM_PROFILE" "$SLP_SYSTEM_TYPE" "$SLP_SYSTEM_PLATFORM" "$SLP_SYSTEM_ENVIRONMENT" "$(slp_support_class)"
  for _slp_line in "${SLP_RESULTS[@]}"; do
    IFS=$'\t' read -r _slp_tag _slp_cid _slp_status _slp_value _slp_comp <<< "$_slp_line"
    slp_selected "$_slp_comp" "$_slp_failed_only" || continue
    printf '%s\n' "$_slp_line"
  done
  printf 'SLP-SUMMARY-V1\tTOTAL=%d\tPASS=%d\tFAIL=%d\tNOT_FOUND=%d\tNOT_APPLICABLE=%d\tERROR=%d\tPOLICY_STATUS=%s\n' \
    "$SLP_TOTAL" "$SLP_PASS" "$SLP_FAIL" "$SLP_NF" "$SLP_NA" "$SLP_ERR" "$SLP_POLICY_STATUS"
}

slp_render_pretty() {
  local _slp_failed_only=$1 _slp_title=$2 _slp_line _slp_tag _slp_cid _slp_status _slp_value _slp_comp
  local _slp_current _slp_required _slp_meta _slp_source _slp_control _slp_extra _slp_st
  printf '=== SecureLinux Policy 1.0.11 — %s ===\n' "$_slp_title"
  printf 'SUPPORT=%s\n' "$(slp_support_class)"
  printf 'SYSTEM=%s ARCH=%s\n' "$SLP_SYSTEM_PRETTY_NAME" "$SLP_SYSTEM_ARCH"
  printf 'PLATFORM=%s\n' "$SLP_SYSTEM_PLATFORM"
  if [[ -n $SLP_SYSTEM_TYPE ]]; then
    printf 'TYPE=%s\n\n' "$SLP_SYSTEM_TYPE"
  else
    printf 'PROFILE=%s\n\n' "$SLP_SYSTEM_PROFILE"
  fi
  slp_pretty_layout_init || return 1
  slp_pretty_separator
  slp_pretty_row 'st' 'source' 'control' 'current' 'required'
  slp_pretty_separator
  for _slp_line in "${SLP_RESULTS[@]}"; do
    IFS=$'\t' read -r _slp_tag _slp_cid _slp_status _slp_value _slp_comp <<< "$_slp_line"
    slp_selected "$_slp_comp" "$_slp_failed_only" || continue
    if ! _slp_meta=$(slp_presentation_for_control "$_slp_cid"); then
      printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2
      return 1
    fi
    IFS=$'\t' read -r _slp_source _slp_control _slp_required _slp_extra <<< "$_slp_meta"
    if [[ -z $_slp_source || -z $_slp_control || -z $_slp_required || -n $_slp_extra ]]; then
      printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2
      return 1
    fi
    if ! _slp_st=$(slp_pretty_status "$_slp_comp"); then
      printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2
      return 1
    fi
    case "$_slp_status" in
      VALUE) _slp_current=$_slp_value ;;
      NOT_FOUND) _slp_current='<absent>' ;;
      NOT_APPLICABLE) _slp_current='<not-applicable>' ;;
      ERROR) _slp_current="not-determined; reason: $_slp_value" ;;
      *) printf '%s\n' 'CHECK_INTERNAL_ERROR' >&2; return 1 ;;
    esac
    slp_pretty_row "$_slp_st" "$_slp_source" "$_slp_control" "$_slp_current" "$_slp_required"
  done
  slp_pretty_separator
  printf 'TOTAL=%d   PASS=%d   FAIL=%d   NOT_FOUND=%d   NOT_APPLICABLE=%d   ERROR=%d   POLICY=%s\n' \
    "$SLP_TOTAL" "$SLP_PASS" "$SLP_FAIL" "$SLP_NF" "$SLP_NA" "$SLP_ERR" "$SLP_POLICY_STATUS"
  if [[ $_slp_title == REPORT ]]; then
    slp_render_unchanged /var/log/securelinux-policy/report.json || return 1
  fi
}

slp_render_unchanged() {
  # Раздел --report: FAIL/ERROR/NOT_FOUND контроли и причина, по которой они оставлены без изменений
  # (у контроля нет APPLY или исход последнего APPLY по его отчёту). $1 — путь отчёта APPLY.
  local _slp_report=$1 _slp_line _slp_tag _slp_cid _slp_status _slp_value _slp_comp
  local -a _slp_failed_ids=()
  for _slp_line in "${SLP_RESULTS[@]}"; do
    IFS=$'\t' read -r _slp_tag _slp_cid _slp_status _slp_value _slp_comp <<< "$_slp_line"
    case "$_slp_comp" in
      FAIL|ERROR|NOT_FOUND) _slp_failed_ids+=("$_slp_cid") ;;
    esac
  done
  (( ${#_slp_failed_ids[@]} > 0 )) || return 0
  command /usr/bin/python3 -I -S -B - "$_slp_report" "${SLP_PRETTY_COLS:-116}" "${_slp_failed_ids[@]}" <<'SLP_PRODUCT_REPORT_EOF'
import json
import os
import stat
import sys

META = json.loads(r'{"FSTEC-CONFIGURATION-2026-1.1-ENCRYPT-METHOD":{"apply":true,"label":"\u00a71.1 encrypt-method"},"FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGE":{"apply":false,"label":"\u00a71.1 existing-password-age","reason":"\u041f\u0430\u0440\u043e\u043b\u044c \u0441\u0442\u0430\u0440\u0448\u0435 90 \u0434\u043d\u0435\u0439 \u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u043b\u0430\u0434\u0435\u043b\u0435\u0446 \u0443\u0447\u0451\u0442\u043d\u043e\u0439 \u0437\u0430\u043f\u0438\u0441\u0438 \u0438\u043b\u0438 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440; APPLY \u0441\u0440\u043e\u043a\u043e\u0432 \u043f\u0430\u0440\u043e\u043b\u044f \u0434\u0430\u0442\u0443 \u0441\u043c\u0435\u043d\u044b \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442."},"FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGING":{"apply":true,"label":"\u00a71.1 existing-password-aging"},"FSTEC-CONFIGURATION-2026-1.1-PASS-MAX-DAYS":{"apply":true,"label":"\u00a71.1 pass-max-days"},"FSTEC-CONFIGURATION-2026-1.1-PASS-MIN-DAYS":{"apply":true,"label":"\u00a71.1 pass-min-days"},"FSTEC-CONFIGURATION-2026-1.1-PASS-WARN-AGE":{"apply":true,"label":"\u00a71.1 pass-warn-age"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-DCREDIT":{"apply":true,"label":"\u00a71.1 pwquality-dcredit"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-ENFORCE-FOR-ROOT":{"apply":true,"label":"\u00a71.1 pwquality-enforce-for-root"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-LCREDIT":{"apply":true,"label":"\u00a71.1 pwquality-lcredit"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-MINLEN":{"apply":true,"label":"\u00a71.1 pwquality-minlen"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-OCREDIT":{"apply":true,"label":"\u00a71.1 pwquality-ocredit"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-RETRY":{"apply":true,"label":"\u00a71.1 pwquality-retry"},"FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-UCREDIT":{"apply":true,"label":"\u00a71.1 pwquality-ucredit"},"FSTEC-CONFIGURATION-2026-1.2-PWHISTORY-ENFORCE-FOR-ROOT":{"apply":true,"label":"\u00