":{"apply":true,"label":"\u00a72.3.1 passwd-mode"},"FSTEC-LINUX-2022-2.3.1-SHADOW-GO-RWX":{"apply":true,"label":"\u00a72.3.1 shadow-go-rwx"},"FSTEC-LINUX-2022-2.3.10-HOME-SENSITIVE-FILES-MODE":{"apply":true,"label":"\u00a72.3.10 home-sensitive-files-mode"},"FSTEC-LINUX-2022-2.3.11-DIR-MODE":{"apply":true,"label":"\u00a72.3.11 dir-mode"},"FSTEC-LINUX-2022-2.3.11-HOME-DIRECTORIES-MODE":{"apply":true,"label":"\u00a72.3.11 home-directories-mode"},"FSTEC-LINUX-2022-2.3.11-HOME-MODE":{"apply":true,"label":"\u00a72.3.11 home-mode"},"FSTEC-LINUX-2022-2.3.2-RUNNING-PROCESS-PATHS-WRITE-PROTECTION":{"apply":false,"label":"\u00a72.3.2 running-process-paths-write-protection","reason":"\u041f\u0440\u0430\u0432\u0430 \u0444\u0430\u0439\u043b\u043e\u0432 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043d\u044b\u0445 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0432 \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440: \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f."},"FSTEC-LINUX-2022-2.3.3-CRON-COMMAND-PATHS-WRITE-PROTECTION":{"apply":true,"label":"\u00a72.3.3 cron-command-paths-write-protection"},"FSTEC-LINUX-2022-2.3.4-SUDO-ROOT-COMMAND-FILES-PROTECTION":{"apply":true,"label":"\u00a72.3.4 sudo-root-command-files-protection"},"FSTEC-LINUX-2022-2.3.5-STARTUP-FILES-WRITE-PROTECTION":{"apply":true,"label":"\u00a72.3.5 startup-files-write-protection"},"FSTEC-LINUX-2022-2.3.6-CRON-D":{"apply":true,"label":"\u00a72.3.6 cron-d"},"FSTEC-LINUX-2022-2.3.6-CRON-DAILY":{"apply":true,"label":"\u00a72.3.6 cron-daily"},"FSTEC-LINUX-2022-2.3.6-CRON-HOURLY":{"apply":true,"label":"\u00a72.3.6 cron-hourly"},"FSTEC-LINUX-2022-2.3.6-CRON-MONTHLY":{"apply":true,"label":"\u00a72.3.6 cron-monthly"},"FSTEC-LINUX-2022-2.3.6-CRON-WEEKLY":{"apply":true,"label":"\u00a72.3.6 cron-weekly"},"FSTEC-LINUX-2022-2.3.6-CRONTAB":{"apply":true,"label":"\u00a72.3.6 crontab"},"FSTEC-LINUX-2022-2.3.7-USER-CRON-FILES-MODE":{"apply":true,"label":"\u00a72.3.7 user-cron-files-mode"},"FSTEC-LINUX-2022-2.3.8-STANDARD-SYSTEM-PATHS-MODE":{"apply":true,"label":"\u00a72.3.8 standard-system-paths-mode"},"FSTEC-LINUX-2022-2.3.9-SUID-SGID-MODE":{"apply":true,"label":"\u00a72.3.9 suid-sgid-mode"},"FSTEC-LINUX-2022-2.4.1-DMESG-RESTRICT":{"apply":true,"label":"\u00a72.4.1 dmesg-restrict"},"FSTEC-LINUX-2022-2.4.2-KPTR-RESTRICT":{"apply":true,"label":"\u00a72.4.2 kptr-restrict"},"FSTEC-LINUX-2022-2.4.3-INIT-ON-ALLOC":{"apply":true,"label":"\u00a72.4.3 init-on-alloc"},"FSTEC-LINUX-2022-2.4.4-SLAB-NOMERGE":{"apply":true,"label":"\u00a72.4.4 slab-nomerge"},"FSTEC-LINUX-2022-2.4.5-IOMMU-FORCE":{"apply":true,"label":"\u00a72.4.5 iommu-force"},"FSTEC-LINUX-2022-2.4.5-IOMMU-PASSTHROUGH":{"apply":true,"label":"\u00a72.4.5 iommu-passthrough"},"FSTEC-LINUX-2022-2.4.5-IOMMU-STRICT":{"apply":true,"label":"\u00a72.4.5 iommu-strict"},"FSTEC-LINUX-2022-2.4.6-RANDOMIZE-KSTACK-OFFSET":{"apply":true,"label":"\u00a72.4.6 randomize-kstack-offset"},"FSTEC-LINUX-2022-2.4.7-MITIGATIONS":{"apply":true,"label":"\u00a72.4.7 mitigations"},"FSTEC-LINUX-2022-2.4.8-BPF-JIT-HARDEN":{"apply":true,"label":"\u00a72.4.8 bpf-jit-harden"},"FSTEC-LINUX-2022-2.5.1-VSYSCALL":{"apply":true,"label":"\u00a72.5.1 vsyscall"},"FSTEC-LINUX-2022-2.5.10-MMAP-MIN-ADDR":{"apply":true,"label":"\u00a72.5.10 mmap-min-addr"},"FSTEC-LINUX-2022-2.5.11-RANDOMIZE-VA-SPACE":{"apply":true,"label":"\u00a72.5.11 randomize-va-space"},"FSTEC-LINUX-2022-2.5.2-PERF-EVENT-PARANOID":{"apply":true,"label":"\u00a72.5.2 perf-event-paranoid"},"FSTEC-LINUX-2022-2.5.3-DEBUGFS":{"apply":true,"label":"\u00a72.5.3 debugfs"},"FSTEC-LINUX-2022-2.5.4-KEXEC-LOAD-DISABLED":{"apply":true,"label":"\u00a72.5.4 kexec-load-disabled"},"FSTEC-LINUX-2022-2.5.5-MAX-USER-NAMESPACES":{"apply":true,"label":"\u00a72.5.5 max-user-namespaces"},"FSTEC-LINUX-2022-2.5.6-UNPRIVILEGED-BPF-DISABLED":{"apply":true,"label":"\u00a72.5.6 unprivileged-bpf-disabled"},"FSTEC-LINUX-2022-2.5.7-UNPRIVILEGED-USERFAULTFD":{"apply":true,"label":"\u00a72.5.7 unprivileged-userfaultfd"},"FSTEC-LINUX-2022-2.5.8-LDISC-AUTOLOAD":{"apply":true,"label":"\u00a72.5.8 ldisc-autoload"},"FSTEC-LINUX-2022-2.5.9-TSX":{"apply":true,"label":"\u00a72.5.9 tsx"},"FSTEC-LINUX-2022-2.6.1-PTRACE-SCOPE":{"apply":true,"label":"\u00a72.6.1 ptrace-scope"},"FSTEC-LINUX-2022-2.6.2-PROTECTED-SYMLINKS":{"apply":true,"label":"\u00a72.6.2 protected-symlinks"},"FSTEC-LINUX-2022-2.6.3-PROTECTED-HARDLINKS":{"apply":true,"label":"\u00a72.6.3 protected-hardlinks"},"FSTEC-LINUX-2022-2.6.4-PROTECTED-FIFOS":{"apply":true,"label":"\u00a72.6.4 protected-fifos"},"FSTEC-LINUX-2022-2.6.5-PROTECTED-REGULAR":{"apply":true,"label":"\u00a72.6.5 protected-regular"},"FSTEC-LINUX-2022-2.6.6-SUID-DUMPABLE":{"apply":true,"label":"\u00a72.6.6 suid-dumpable"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-1-AUDITD-PACKAGE":{"apply":true,"label":"\u00a7app2:1 auditd-package"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-2-AUDITD-SERVICE":{"apply":true,"label":"\u00a7app2:2 auditd-service"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-ADMIN-SPACE-LEFT-ACTION":{"apply":true,"label":"\u00a7app2:3 admin-space-left-action"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-DISK-FULL-ACTION":{"apply":true,"label":"\u00a7app2:3 disk-full-action"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FILE":{"apply":true,"label":"\u00a7app2:3 log-file"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FORMAT":{"apply":true,"label":"\u00a7app2:3 log-format"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-GROUP":{"apply":true,"label":"\u00a7app2:3 log-group"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE":{"apply":true,"label":"\u00a7app2:3 max-log-file"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE-ACTION":{"apply":true,"label":"\u00a7app2:3 max-log-file-action"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-NUM-LOGS":{"apply":true,"label":"\u00a7app2:3 num-logs"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-SPACE-LEFT-ACTION":{"apply":true,"label":"\u00a7app2:3 space-left-action"},"FSTEC-LOGGING-2025-APPENDIX2-LINUX-4-AUDIT-RULES":{"apply":true,"label":"\u00a7app2:4 audit-rules"},"FSTEC-LOGGING-2025-MAIN-5-AUDIT-LOG-FREE-SPACE":{"apply":false,"label":"\u00a7main:5 audit-log-free-space","reason":"\u041c\u0435\u0441\u0442\u043e \u0432 \u0444\u0430\u0439\u043b\u043e\u0432\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u0435 /var/log/audit \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440."}}')
LIMIT = 8 * 1024 * 1024


def clean(value):
    text = "" if value is None else str(value)
    return "".join(ch if (ch >= " " and ch != "\x7f") else "?" for ch in text)


def load_report(path):
    """(отчёт, None) или (None, причина, по которой отчёт последнего APPLY не используется)."""
    parent = os.path.dirname(path)
    try:
        pst = os.lstat(parent)
    except FileNotFoundError:
        return None, "APPLY не выполнялся: каталог отчёта " + parent + " отсутствует."
    except OSError as exc:
        return None, "каталог отчёта APPLY недоступен: " + clean(exc.strerror) + "."
    if not stat.S_ISDIR(pst.st_mode) or pst.st_uid != 0 or pst.st_mode & 0o022:
        return None, "каталог отчёта APPLY " + parent + " недоверенный: отчёт не используется."
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
    except FileNotFoundError:
        return None, "APPLY не выполнялся: отчёт " + path + " отсутствует."
    except PermissionError:
        return None, "нет доступа к отчёту APPLY " + path + ": запустите --report от root."
    except OSError as exc:
        return None, "отчёт APPLY недоступен: " + clean(exc.strerror) + "."
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1 or st.st_uid != 0 or st.st_mode & 0o022:
            return None, "отчёт APPLY " + path + " недоверенный: отчёт не используется."
        parts, total = [], 0
        while True:
            chunk = os.read(fd, 65536)
            if not chunk:
                break
            total += len(chunk)
            if total > LIMIT:
                return None, "отчёт APPLY больше 8 MiB: отчёт не используется."
            parts.append(chunk)
    except OSError as exc:
        return None, "отчёт APPLY не прочитан: " + clean(exc.strerror) + "."
    finally:
        os.close(fd)
    try:
        data = json.loads(b"".join(parts).decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None, "отчёт APPLY повреждён: отчёт не используется."
    if (not isinstance(data, dict) or data.get("schema") != "SLP-APPLY-REPORT-V2"
            or not isinstance(data.get("controls"), list) or not isinstance(data.get("dry_run"), bool)):
        return None, "отчёт APPLY неизвестного формата: отчёт не используется."
    if data.get("complete") is not True:
        return None, "последний запуск APPLY не завершён: отчёт неполный и не используется."
    records = {}
    for record in data["controls"]:
        if (not isinstance(record, dict) or not isinstance(record.get("control_id"), str)
                or record["control_id"] in records):
            return None, "отчёт APPLY повреждён: отчёт не используется."
        records[record["control_id"]] = record
    expected = {cid for cid, item in META.items() if item["apply"]}
    if set(records) != expected:
        return None, "отчёт APPLY относится к другому составу контролей: выполните --apply этой версии."
    data["records"] = records
    return data, None


def apply_rows(record):
    outcome = clean(record.get("outcome"))
    reason = record.get("reason")
    rows = [("apply", outcome + ("; " + clean(reason) if reason not in (None, "") else ""))]
    result = record.get("mechanism_result")
    decision = result.get("operator_decision") if isinstance(result, dict) else None
    if isinstance(decision, dict):
        kind = decision.get("class")
        if kind == "ADMIN_ACTION_REQUIRED":
            rows.append(("note", clean(decision.get("action"))))
        elif kind == "BOOT_PARAMETER_ADMIN_DECISION":
            rows.append(("add", clean(decision.get("value"))))
            rows.append(("risk", clean(decision.get("risk")) + "."))
        elif kind == "SERVICE_MANAGED_PARAMETER":
            rows.append(("note", clean(decision.get("parameter")) + "=" + clean(decision.get("current_value"))
                         + ": обнаружен штатный механизм " + clean(decision.get("service"))
                         + ", управляющий этим параметром."))
    return rows


def pieces(text, width, words):
    if not text:
        return [""]
    if not words:
        return [text[i:i + width] for i in range(0, len(text), width)]
    out, line = [], ""
    for word in text.split(" "):
        while len(word) > width:
            if line:
                out.append(line)
                line = ""
            out.append(word[:width])
            word = word[width:]
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            out.append(line)
            line = word
    out.append(line)
    return out


def main():
    if len(sys.argv) < 4:
        return 1
    path, cols_text, ids = sys.argv[1], sys.argv[2], sys.argv[3:]
    cols = int(cols_text) if cols_text.isdigit() and len(cols_text) <= 4 else 116
    if not 40 <= cols <= 1000:
        cols = 116
    if any(cid not in META for cid in ids):
        return 1
    report, problem = None, None
    if any(META[cid]["apply"] for cid in ids):
        report, problem = load_report(path)
    entries = []
    for cid in ids:
        item = META[cid]
        if not item["apply"]:
            rows = [("check", item["reason"])]
        elif report is None:
            rows = [("apply", "исправляется --apply.")]
        else:
            rows = apply_rows(report["records"][cid])
        entries.append((clean(item["label"]), rows))
    wtype = 6
    wcontrol = min(max(12, max(len(label) for label, _rows in entries)), max(12, cols // 3))
    wmessage = cols - 9 - wcontrol - wtype
    if wmessage < 12:
        return 1
    print()
    print("Оставлено без изменений — причины (%d):" % len(entries))
    print("check — у контроля нет автоматического исправления; apply — исход последнего APPLY.")
    if report is not None:
        print("Последний APPLY: %s%s." % (clean(report.get("finished_at")),
                                         " (--dry-run)" if report["dry_run"] else ""))
    elif problem is not None:
        print("Отчёт APPLY не используется: " + problem)
    sep = "-" * (wcontrol + 2) + "+" + "-" * (wtype + 2) + "+" + "-" * (wmessage + 2) + "+"

    def row(control, kind, message):
        cc = pieces(control, wcontrol, False)
        kc = pieces(kind, wtype, False)
        mc = pieces(message, wmessage, True)
        for i in range(max(len(cc), len(kc), len(mc))):
            c = cc[i] if i < len(cc) else ""
            k = kc[i] if i < len(kc) else ""
            m = mc[i] if i < len(mc) else ""
            print(" %-*s | %-*s | %-*s |" % (wcontrol, c, wtype, k, wmessage, m))

    print(sep)
    row("control", "type", "message")
    print(sep)
    for label, rows in entries:
        for n, (kind, message) in enumerate(rows):
            row(label if n == 0 else "", kind, message)
    print(sep)
    return 0


try:
    RC = main()
except Exception:
    RC = 1
if RC != 0:
    print("CHECK_INTERNAL_ERROR", file=sys.stderr)
raise SystemExit(RC)

SLP_PRODUCT_REPORT_EOF
}

slp_render_json() {
  local _slp_failed_only=$1 _slp_line _slp_tag _slp_cid _slp_status _slp_value _slp_comp _slp_first=1 _slp_filter=all
  (( _slp_failed_only == 1 )) && _slp_filter=failed
  printf '{"schema":"SLP-REPORT-V1","filter":"%s","platform":{"system":"%s","id":"%s","version_id":"%s","arch":"%s","profile":"%s","type":"%s","platform_id":"%s","environment_id":"%s","support":"%s"},"policy_status":"%s","summary":{"total":%d,"pass":%d,"fail":%d,"not_found":%d,"not_applicable":%d,"error":%d},"results":[' \
    "$_slp_filter" "$(slp_json_escape "$SLP_SYSTEM_PRETTY_NAME")" "$(slp_json_escape "$SLP_SYSTEM_ID")" \
    "$(slp_json_escape "$SLP_SYSTEM_VERSION_ID")" "$(slp_json_escape "$SLP_SYSTEM_ARCH")" \
    "$(slp_json_escape "$SLP_SYSTEM_PROFILE")" "$(slp_json_escape "$SLP_SYSTEM_TYPE")" "$(slp_json_escape "$SLP_SYSTEM_PLATFORM")" \
    "$(slp_json_escape "$SLP_SYSTEM_ENVIRONMENT")" "$(slp_json_escape "$(slp_support_class)")" "$SLP_POLICY_STATUS" "$SLP_TOTAL" "$SLP_PASS" "$SLP_FAIL" "$SLP_NF" "$SLP_NA" "$SLP_ERR"
  for _slp_line in "${SLP_RESULTS[@]}"; do
    IFS=$'\t' read -r _slp_tag _slp_cid _slp_status _slp_value _slp_comp <<< "$_slp_line"
    slp_selected "$_slp_comp" "$_slp_failed_only" || continue
    if (( _slp_first == 0 )); then printf ','; fi
    _slp_first=0
    printf '{"control_id":"%s","observation":"%s","value":"%s","result":"%s"}' \
      "$(slp_json_escape "$_slp_cid")" "$(slp_json_escape "$_slp_status")" "$(slp_json_escape "$_slp_value")" "$(slp_json_escape "$_slp_comp")"
  done
  printf ']}\n'
}

slp_run_check() {
  local _slp_format=$1 _slp_failed_only=$2 _slp_title=${3:-CHECK}
  slp_target_preflight || return $?
  slp_collect_policy || return $?
  case "$_slp_format" in
    pretty) slp_render_pretty "$_slp_failed_only" "$_slp_title" ;;
    raw) slp_render_raw "$_slp_failed_only" ;;
    json) slp_render_json "$_slp_failed_only" ;;
    *) return 2 ;;
  esac
  return "$SLP_POLICY_RC"
}

