def now():
    return datetime.datetime.now(datetime.timezone.utc).astimezone().isoformat(timespec="seconds")

class StateRefused(Exception):
    pass

def _refuse(reason, detail):
    raise StateRefused(reason, detail)

def _check_parent():
    parent = os.path.dirname(STATE_DIR)
    try:
        st = os.stat(parent)
    except OSError as exc:
        _refuse("reporting:state-parent-unavailable", f"{parent}: {exc.strerror}")
    if st.st_uid != PARENT_TRUSTED_UID:
        _refuse("reporting:state-parent-owner", f"{parent} owner uid={st.st_uid}, expected {PARENT_TRUSTED_UID}")
    if st.st_mode & 0o002:
        _refuse("reporting:state-parent-mode", f"{parent} is world-writable (mode {st.st_mode & 0o7777:04o})")
    if st.st_mode & 0o020:
        try:
            group = grp.getgrgid(st.st_gid).gr_name
        except KeyError:
            group = None
        if st.st_gid != 0 and group not in PARENT_WRITABLE_GROUPS:
            _refuse("reporting:state-parent-mode", f"{parent} is group-writable by gid={st.st_gid} (mode {st.st_mode & 0o7777:04o})")

def _acquire_lock(dir_st):
    # dfd остаётся открытым до конца работы (см. _STATE_DFD): все последующие
    # записи (отчёт, журналы) идут относительно него, а не по строке STATE_DIR,
    # иначе подмена каталога после проверки уходит мимо проверенного inode.
    global _LOCK_FD, _STATE_DFD
    flags = os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_CLOEXEC
    dfd = os.open(STATE_DIR, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    ok = False
    try:
        opened = os.fstat(dfd)
        if (opened.st_dev, opened.st_ino) != (dir_st.st_dev, dir_st.st_ino):
            _refuse("reporting:state-dir-invalid", f"{STATE_DIR} changed during validation")
        fd = os.open(LOCK_NAME, flags, 0o600, dir_fd=dfd)
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1 or st.st_uid != TRUSTED_UID or st.st_mode & 0o022:
            os.close(fd)
            _refuse("reporting:state-lock-invalid", f"{LOCK_PATH} is not a regular root-owned single-link file without group/other write")
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            os.close(fd)
            _refuse("reporting:already-running", f"another instance already running (lock {LOCK_PATH})")
        _LOCK_FD = fd
        _STATE_DFD = dfd
        ok = True
    finally:
        if not ok:
            os.close(dfd)

def ensure_state_dir():
    _check_parent()
    try:
        os.mkdir(STATE_DIR, 0o700)
    except FileExistsError:
        pass
    except OSError as exc:
        _refuse("reporting:state-dir-unavailable", f"{STATE_DIR}: {exc.strerror}")
    st = os.lstat(STATE_DIR)
    if stat.S_ISLNK(st.st_mode):
        _refuse("reporting:state-dir-symlink", f"{STATE_DIR} is a symlink")
    if not stat.S_ISDIR(st.st_mode):
        _refuse("reporting:state-dir-invalid", f"{STATE_DIR} is not a directory")
    if st.st_uid != TRUSTED_UID:
        _refuse("reporting:state-dir-owner", f"{STATE_DIR} owner uid={st.st_uid}, expected {TRUSTED_UID}")
    if st.st_mode & 0o022:
        _refuse("reporting:state-dir-mode", f"{STATE_DIR} is group/other-writable (mode {st.st_mode & 0o7777:04o})")
    try:
        _acquire_lock(st)
    except OSError as exc:
        _refuse("reporting:state-lock-unavailable", f"{LOCK_PATH}: {exc.strerror}")

def _mkstemp_at(dfd, prefix):
    # Аналог tempfile.mkstemp, но относительно удерживаемого дескриптора
    # каталога (dir_fd), а не по строке пути.
    for _ in range(100):
        name = prefix + os.urandom(8).hex()
        try:
            fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=dfd)
        except FileExistsError:
            continue
        return fd, name
    raise OSError("reporting:tmp-name-exhausted")

def atomic_report(payload):
    fd, tmp = _mkstemp_at(_STATE_DFD, ".report.json.")
    try:
        data = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp, REPORT_PATH, src_dir_fd=_STATE_DFD, dst_dir_fd=_STATE_DFD)
        os.fsync(_STATE_DFD)
    except Exception:
        try:
            os.unlink(tmp, dir_fd=_STATE_DFD)
        except FileNotFoundError:
            pass
        raise

def append_log(name, message):
    flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(name, flags, 0o600, dir_fd=_STATE_DFD)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
            raise RuntimeError("reporting:log-target-invalid")
        os.write(fd, (f"[{now()}] {message}\n").encode("utf-8"))
        os.fsync(fd)
    finally:
        os.close(fd)

def ensure_log_file(name):
    flags = os.O_WRONLY | os.O_CREAT
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(name, flags, 0o600, dir_fd=_STATE_DFD)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
            raise RuntimeError("reporting:log-target-invalid")
        os.fsync(fd)
    finally:
        os.close(fd)

def _write_all(fd, data):
    view = memoryview(data)
    while view:
        view = view[os.write(fd, view):]

def make_backup():
    """Каталог STATE_DIR/backup/<время>/ (0700) с files/ и пустыми журналами; путь каталога."""
    try:
        os.mkdir(BACKUP_PARENT, 0o700, dir_fd=_STATE_DFD)
    except FileExistsError:
        pass
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
    pfd = os.open(BACKUP_PARENT, flags, dir_fd=_STATE_DFD)
    try:
        st = os.fstat(pfd)
        if st.st_uid != TRUSTED_UID or st.st_mode & 0o077:
            raise RuntimeError("backup:dir-invalid")
        base = datetime.datetime.now().strftime("%Y%m%dT%H%M%S")
        for n in range(100):
            name = base if n == 0 else "%s-%d" % (base, n)
            try:
                os.mkdir(name, 0o700, dir_fd=pfd)
                break
            except FileExistsError:
                continue
        else:
            raise RuntimeError("backup:name-exhausted")
        rfd = os.open(name, flags, dir_fd=pfd)
    finally:
        os.close(pfd)
    os.mkdir("files", 0o700, dir_fd=rfd)
    create = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_APPEND
    for log in ("files", "modes", "runtime", "services", "commands"):
        _BK[log] = os.open(log + ".tsv", create, 0o600, dir_fd=rfd)
    os.fsync(rfd)
    os.close(rfd)
    return os.path.join(STATE_DIR, BACKUP_PARENT, name)

def _escape(text):
    return text.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n")

def _bk_line(log, *fields):
    data = ("\t".join(_escape(str(f)) for f in fields) + "\n").encode("utf-8", "surrogateescape")
    view = memoryview(data)
    while view:
        view = view[os.write(_BK[log], view):]
    os.fsync(_BK[log])

def _full(path, dir_fd=None):
    text = os.fsdecode(path)
    if not os.path.isabs(text):
        base = os.readlink("/proc/self/fd/%d" % dir_fd) if dir_fd is not None else os.getcwd()
        text = os.path.join(base, text)
    return os.path.normpath(text)

def _outside_state(path):
    return path != STATE_DIR and not path.startswith(STATE_DIR.rstrip("/") + "/")

def backup_file(path):
    """Прежнее состояние пути до первого изменения этим запуском: absent, symlink, file (копия
    в files/<путь>) или other. Путь отмечается сохранённым только после записи копии и журнала."""
    if BACKUP_DIR is None or path in _BK_SEEN["files"] or path in _BK_NEW or not _outside_state(path):
        return
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        _bk_line("files", "absent", "-", "-", "-", path, "")
        _BK_SEEN["files"].add(path)
        _BK_NEW.add(path)
        return
    meta = ("%04o" % stat.S_IMODE(st.st_mode), st.st_uid, st.st_gid, path)
    if stat.S_ISLNK(st.st_mode):
        _bk_line("files", "symlink", *meta, os.readlink(path))
        _BK_SEEN["files"].add(path)
        return
    if not stat.S_ISREG(st.st_mode):
        _bk_line("files", "other", *meta, "")
        _BK_SEEN["files"].add(path)
        return
    if st.st_size > BACKUP_FILE_LIMIT or _BK_TOTAL[0] + st.st_size > BACKUP_TOTAL_LIMIT:
        raise OSError(errno.EFBIG, "backup:size-limit")
    fs = os.statvfs(BACKUP_DIR)
    if fs.f_bavail * fs.f_frsize < st.st_size + BACKUP_RESERVE:
        raise OSError(errno.ENOSPC, "backup:no-space")
    dest = os.path.join(BACKUP_DIR, "files", path.lstrip("/"))
    os.makedirs(os.path.dirname(dest), 0o700, exist_ok=True)
    created = False
    try:
        src = _ORIG["open"](path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        try:
            dst = _ORIG["open"](dest, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
            created = True
            try:
                while True:
                    chunk = os.read(src, 1 << 20)
                    if not chunk:
                        break
                    view = memoryview(chunk)
                    while view:
                        view = view[os.write(dst, view):]
                os.fsync(dst)
            finally:
                os.close(dst)
        finally:
            os.close(src)
        _bk_line("files", "file", *meta, "")
    except BaseException:
        # Незавершённая копия удаляется: повторная попытка сохранит файл заново.
        if created:
            try:
                _ORIG["unlink"](dest)
            except OSError:
                pass
        raise
    _BK_TOTAL[0] += st.st_size
    _BK_SEEN["files"].add(path)

def backup_mode(path, st):
    if BACKUP_DIR is None or path in _BK_SEEN["modes"] or path in _BK_NEW or not _outside_state(path):
        return
    _bk_line("modes", "%04o" % stat.S_IMODE(st.st_mode), st.st_uid, st.st_gid, path)
    _BK_SEEN["modes"].add(path)

def backup_runtime(path):
    if path in _BK_SEEN["runtime"]:
        return
    fd = _ORIG["open"](path, os.O_RDONLY | os.O_CLOEXEC)
    try:
        value = os.read(fd, 4096).decode("utf-8", "replace").strip()
    finally:
        os.close(fd)
    _bk_line("runtime", path, value)
    _BK_SEEN["runtime"].add(path)

def backup_command(argv):
    name = os.path.basename(str(argv[0]))
    words = [str(a) for a in argv[1:]]
    verb = next((w for w in words if not w.startswith("-")), "")
    if name == "systemctl":
        if verb in SYSTEMCTL_READ_ONLY:
            return
        units = words[words.index("--") + 1:] if "--" in words else words[words.index(verb) + 1:] if verb else []
        for unit in units:
            if unit.startswith("-") or unit in _BK_SEEN["services"]:
                continue
            state = []
            for query in ("is-enabled", "is-active"):
                cp = _ORIG["run"]([str(argv[0]), query, "--", unit], stdin=subprocess.DEVNULL,
                                  stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=60)
                state.append(cp.stdout.decode("utf-8", "replace").strip() or "unknown")
            _bk_line("services", unit, *state)
            _BK_SEEN["services"].add(unit)
    elif name in COMMAND_FILES:
        for path in COMMAND_FILES[name]:
            backup_file(path)
    elif not (name == "apt-get" and verb == "install"):
        return
    _bk_line("commands", now(), " ".join(str(a) for a in argv))

def _hook(name, before, after=None):
    original = getattr(os, name) if name != "run" else subprocess.run
    _ORIG[name] = original

    def wrapper(*args, **kwargs):
        # Ошибка записи прежнего состояния останавливает изменение до вызова (ничего не подавляется).
        try:
            before(*args, **kwargs)
        except OSError as exc:
            reason = exc.strerror if str(exc.strerror or "").startswith("backup:") else "backup:record-failed"
            raise OSError(exc.errno or errno.EIO, reason)
        except Exception:
            raise OSError(errno.EIO, "backup:record-failed")
        result = original(*args, **kwargs)
        if after is not None:
            after(result, *args, **kwargs)
        return result
    return wrapper

def _after_open(fd, path, flags, *args, dir_fd=None, **kwargs):
    if not isinstance(path, int) and flags & os.O_CREAT and flags & os.O_EXCL:
        _BK_NEW.add(_full(path, dir_fd))

def _before_replace(src, dst, *args, src_dir_fd=None, dst_dir_fd=None, **kwargs):
    backup_file(_full(dst, dst_dir_fd))

def _before_unlink(path, *args, dir_fd=None, **kwargs):
    backup_file(_full(path, dir_fd))

def _before_open(path, flags, *args, dir_fd=None, **kwargs):
    if not flags & (os.O_WRONLY | os.O_RDWR) or flags & os.O_EXCL or isinstance(path, int):
        return
    full = _full(path, dir_fd)
    if full.startswith("/proc/sys/"):
        backup_runtime(full)
    elif not full.startswith(("/proc/", "/sys/", "/dev/")):
        backup_file(full)

def _before_mode(target, *args, dir_fd=None, follow_symlinks=True, **kwargs):
    if isinstance(target, int):
        backup_mode(os.readlink("/proc/self/fd/%d" % target), os.fstat(target))
        return
    try:
        st = os.stat(target, dir_fd=dir_fd, follow_symlinks=follow_symlinks)
    except FileNotFoundError:
        return  # объекта нет: сохранять нечего, исходный вызов сам вернёт ENOENT
    full = _full(target, dir_fd)
    backup_mode(os.path.realpath(full) if follow_symlinks else full, st)

def _before_lchown(target, *args, **kwargs):
    _before_mode(target, follow_symlinks=False)

def _before_run(*args, **kwargs):
    argv = args[0] if args else kwargs.get("args")
    if isinstance(argv, (list, tuple)) and argv:
        backup_command(argv)

def install_backup_hooks():
    for name, before in (("replace", _before_replace), ("rename", _before_replace),
                         ("unlink", _before_unlink), ("remove", _before_unlink),
                         ("fchmod", _before_mode), ("chmod", _before_mode), ("fchown", _before_mode),
                         ("chown", _before_mode), ("lchown", _before_lchown)):
        setattr(os, name, _hook(name, before))
    os.open = _hook("open", _before_open, _after_open)
    subprocess.run = _hook("run", _before_run)

def operator_record(raw, meta, outcome, reason, decision=None):
    """Исход, назначенный dispatcher по наблюдению механизма без изменений (dry-run):
    пропуск --skip или блок TYPE=DESKTOP."""
    mechanism_result = {k: v for k, v in raw.items() if k not in COMMON}
    mechanism_result["dry_run"] = DRY_RUN
    if decision is not None:
        mechanism_result["operator_decision"] = decision
    return {
        "control_id": raw["control_id"],
        "mechanism_id": meta["mechanism_id"],
        "outcome": outcome,
        "reason": reason,
        "actions_attempted": raw["actions_attempted"],
        "step_rc": "0" if outcome == "SKIPPED_BY_OPERATOR" else "nonzero",
        "mutation_performed": False,
        "transaction_commit": "NOT_STARTED",
        "started_at": raw["started_at"],
        "finished_at": raw["finished_at"],
        "mechanism_result": mechanism_result,
    }

def load_route(meta):
    raw = base64.b64decode(meta["source_b64"], validate=True)
    if __import__("hashlib").sha256(raw).hexdigest() != meta["implementation_sha256"]:
        raise RuntimeError("routing:embedded-implementation-sha-mismatch")
    ns = {"__name__": "_slp_embedded_" + meta["mechanism_id"].replace("-", "_"), "__file__": "<embedded>"}
    exec(compile(raw, "<embedded:" + meta["mechanism_id"] + ">", "exec"), ns)
    if ns.get("MECHANISM_ID") != meta["mechanism_id"] or ns.get("ADAPTER_ID") != meta["adapter_id"]:
        raise RuntimeError("routing:embedded-implementation-identity-mismatch")
    if not callable(ns.get("execute_control")) or not callable(ns.get("control_result_to_report")):
        raise RuntimeError("routing:embedded-implementation-api-missing")
    return ns

def unavailable_record(control, started, finished):
    return {
        "control_id": control["control_id"],
        "mechanism_id": None,
        "outcome": "ABORTED_PRECONDITION_OTHER",
        "reason": "routing:mechanism-unavailable",
        "actions_attempted": ["P0_ELIGIBILITY"],
        "step_rc": "nonzero",
        "mutation_performed": False,
        "transaction_commit": "NOT_STARTED",
        "started_at": started,
        "finished_at": finished,
        "mechanism_result": {"parameter_kind": control["parameter_kind"]},
    }

def crash_record(control, meta, started, finished, exc):
    return {
        "control_id": control["control_id"],
        "mechanism_id": None if meta is None else meta["mechanism_id"],
        "outcome": "FAILED_NOT_COMMITTED",
        "reason": "mechanism:unhandled-exception",
        "actions_attempted": [],
        "step_rc": "nonzero",
        "mutation_performed": None,
        "transaction_commit": "UNKNOWN",
        "started_at": started,
        "finished_at": finished,
        "mechanism_result": {"error_type": type(exc).__name__, "error_message": str(exc)},
    }

def _terminal_scalar(value, label):
    if value is None or isinstance(value, (dict, list, tuple, set)):
        raise RuntimeError("presentation:" + label + "-invalid")
    text = str(value)
    if not text or "\n" in text or "\r" in text:
        raise RuntimeError("presentation:" + label + "-invalid")
    return text

def _table_chunks(value, width, label):
    text = _terminal_scalar(value, label) if value != "" else ""
    if not text:
        return [""]
    return [text[i:i + width] for i in range(0, len(text), width)]

def _word_chunks(value, width, label):
    # Перенос по пробелам; слово длиннее колонки режется по ширине.
    text = _terminal_scalar(value, label) if value != "" else ""
    chunks, line = [], ""
    for word in text.split(" "):
        while len(word) > width:
            if line:
                chunks.append(line)
                line = ""
            chunks.append(word[:width])
            word = word[width:]
        if not word:
            continue
        if line and len(line) + 1 + len(word) > width:
            chunks.append(line)
            line = word
        else:
            line = line + " " + word if line else word
    chunks.append(line)
    return chunks

def _terminal_columns():
    try:
        cols = os.get_terminal_size(sys.stdout.fileno()).columns
    except (OSError, ValueError):
        return 116
    if not isinstance(cols, int) or cols < 40 or cols > 1000:
        return 116
    return cols


def _compact_outcome(outcome):
    exact = _terminal_scalar(outcome, "outcome")
    mapping = {
        "ALREADY_COMPLIANT": "ok",
        "NOT_APPLICABLE": "na",
        "APPLIED": "done",
        "APPLIED_PARTIAL": "part",
        "PENDING_REBOOT": "boot",
        "DRY_RUN_WOULD_APPLY": "would",
        "ABORTED_PRECONDITION_CONFLICT": "block",
        "ABORTED_PRECONDITION_OTHER": "abort",
        "FAILED_NOT_COMMITTED": "fail",
        "FAILED_COMPENSATION": "fail",
        "SKIPPED_BY_OPERATOR": "skip",
    }
    return mapping.get(exact, exact.lower())

PRETTY_COLUMNS = _terminal_columns()
PRETTY_IS_TTY = sys.stdout.isatty()
BLOCKS = []

def _terminal_layout(columns=None):
    if columns is None and not PRETTY_IS_TTY:
        columns = 116
    cols = PRETTY_COLUMNS if columns is None else columns
    if cols < 90:
        return ("vertical", cols, (8, cols - 14))
    # source от 100 колонок — 30 символов, «fstec-configuration-2026 §11.2» в одну строку;
    # место отдают control и current (решение пользователя 26.09.2026: source без переносов).
    if cols < 100:
        wsrc, wc, req_min = 18, 24, 10
    elif cols < 110:
        wsrc, wc, req_min = 30, 24, 12
    elif cols < 120:
        wsrc, wc, req_min = 30, 28, 14
    else:
        wsrc, wc, req_min = 30, 32, 16
    ws = 5
    available = cols - 15
    remaining = available - ws - wsrc - wc
    if remaining <= req_min:
        raise RuntimeError("presentation:terminal-width-invalid")
    wcur_base = min(43, remaining - req_min)
    # current отдаёт required 10 символов, но не становится уже 12.
    wcur = max(min(12, wcur_base), wcur_base - 10)
    wreq = remaining - wcur
    return ("table", cols, (ws, wsrc, wc, wcur, wreq))

def _emit_vertical_field(label, value, widths):
    wfield, wvalue = widths
    chunks = _table_chunks(value, wvalue, label) if value else [""]
    for i, chunk in enumerate(chunks):
        field = label if i == 0 else ""
        print(f" {field:<{wfield}} | {chunk:<{wvalue}} |")

def _emit_table_row(st, source, control, current, required):
    mode, _cols, widths = _terminal_layout()
    if mode == "vertical":
        if st == "st" and source == "source" and control == "control":
            wfield, wvalue = widths
            print(f" {'field':<{wfield}} | {'value':<{wvalue}} |")
            return
        _emit_vertical_field("st", st, widths)
        _emit_vertical_field("source", source, widths)
        _emit_vertical_field("control", control, widths)
        _emit_vertical_field("current", current, widths)
        _emit_vertical_field("required", required, widths)
        return
    ws, wsrc, wc, wcur, wreq = widths
    values = (st, source, control, current, required)
    labels = ("st", "source", "display-control", "current", "required")
    chunks = [_table_chunks(value, width, label) for value, width, label in zip(values, widths, labels)]
    rows = max(len(item) for item in chunks)
    for i in range(rows):
        parts = [item[i] if i < len(item) else "" for item in chunks]
        print(
            f" {parts[0]:<{ws}} | {parts[1]:<{wsrc}} | {parts[2]:<{wc}} | "
            f"{parts[3]:<{wcur}} | {parts[4]:<{wreq}} |"
        )

def _emit_separator():
    mode, _cols, widths = _terminal_layout()
    if mode == "vertical":
        wfield, wvalue = widths
        print("-" * (wfield + 2) + "+" + "-" * (wvalue + 2) + "+")
        return
    ws, wsrc, wc, wcur, wreq = widths
    print(
        "-" * (ws + 2) + "+"
        + "-" * (wsrc + 2) + "+"
        + "-" * (wc + 2) + "+"
        + "-" * (wcur + 2) + "+"
        + "-" * (wreq + 2) + "+"
    )

def _current_display(record):
    mechanism_result = record.get("mechanism_result")
    if not isinstance(mechanism_result, dict):
        return "not-determined"
    # sysctl отдаёт runtime_*, режимы файлов — resulting_mode/current_mode, параметры ядра — cmdline_current,
    # доступ к su — policy_current.
    for field in ("runtime_after", "runtime_before", "resulting_mode", "current_mode", "cmdline_current",
                  "policy_current"):
        value = mechanism_result.get(field)
        if value is not None:
            return _terminal_scalar(value, "current")
    return "not-determined"

def _block_entry(record, control):
    # Причина отказа видна администратору для обоих исходов ABORTED_PRECONDITION_*.
    if record.get("outcome") not in ("ABORTED_PRECONDITION_CONFLICT", "ABORTED_PRECONDITION_OTHER"):
        return None
    if record.get("step_rc") == "0" or record.get("mutation_performed") is not False:
        raise RuntimeError("presentation:block-invariant")
    record_id = _terminal_scalar(record.get("control_id"), "control-id")
    control_id = _terminal_scalar(control.get("control_id"), "control-id")
    if record_id != control_id:
        raise RuntimeError("presentation:control-id-mismatch")
    display_control = _block_control_label(control)
    detail = _terminal_scalar(record.get("reason"), "reason")
    entry = {"control": display_control, "rows": [("detail", detail)], "admin": False, "risk": None,
             "order": control["order"]}
    mechanism_result = record.get("mechanism_result")
    if not isinstance(mechanism_result, dict):
        raise RuntimeError("presentation:block-mechanism-result-invalid")
    decision = mechanism_result.get("operator_decision")
    if decision is not None:
        if not isinstance(decision, dict) or decision.get("required") is not True:
            raise RuntimeError("presentation:operator-decision-invalid")
        if decision.get("class") == "SERVICE_MANAGED_PARAMETER":
            service = _terminal_scalar(decision.get("service"), "service")
            parameter = _terminal_scalar(decision.get("parameter"), "parameter")
            current_value = _terminal_scalar(decision.get("current_value"), "current-value")
            entry["rows"].append(
                ("note", f"{parameter}={current_value}: обнаружен штатный механизм {service}, управляющий этим параметром.")
            )
        elif decision.get("class") == "BOOT_PARAMETER_ADMIN_DECISION":
            value = _terminal_scalar(decision.get("value"), "value")
            risk = _terminal_scalar(decision.get("risk"), "risk")
            # Код причины остаётся в JSON-отчёте; инструкция add печатается над таблицей.
            entry["rows"] = [("add", value)]
            entry["risk"] = risk + "."
        elif decision.get("class") == "ADMIN_ACTION_REQUIRED":
            # Готовое действие администратора (2.2.1, решение пользователя 25.09.2026).
            entry["rows"].append(("note", _terminal_scalar(decision.get("action"), "action")))
        else:
            raise RuntimeError("presentation:operator-decision-invalid")
        entry["admin"] = True
    return entry

def _block_control_label(control):
    source = _terminal_scalar(control.get("source"), "source")
    if "§" not in source:
        raise RuntimeError("presentation:block-locator-missing")
    display_control = _terminal_scalar(control.get("display_control"), "display-control")
    return "§" + source.rsplit("§", 1)[1] + " " + display_control

def emit_control_result(record, control):
    control_id = _terminal_scalar(record.get("control_id"), "control-id")
    if control_id != _terminal_scalar(control.get("control_id"), "control-id"):
        raise RuntimeError("presentation:control-id-mismatch")
    outcome = _compact_outcome(record.get("outcome"))
    source = _terminal_scalar(control.get("source"), "source")
    display_control = _terminal_scalar(control.get("display_control"), "display-control")
    current = _current_display(record)
    required = _terminal_scalar(control.get("required"), "required")
    _emit_table_row(outcome, source, display_control, current, required)
    block = _block_entry(record, control)
    if block is not None:
        BLOCKS.append(block)

def apply_handoff(payload):
    # Итог APPLY передаётся оболочке через дескриптор 3: таблица блоков, строки check и итоговая
    # строка печатаются после CHECK контролей без APPLY (решение пользователя 02.10.2026, вариант 1).
    controls = payload.get("controls")
    if not isinstance(controls, list):
        raise RuntimeError("presentation:controls-invalid")
    counts = {}
    for record in controls:
        if not isinstance(record, dict):
            raise RuntimeError("presentation:record-invalid")
        outcome = _terminal_scalar(record.get("outcome"), "outcome")
        counts[outcome] = counts.get(outcome, 0) + 1
    label_width = max((len(_block_control_label(c)) for c in APPLY_CONTROLS), default=12)
    data = {
        "schema": "SLP-APPLY-HANDOFF-V1",
        "blocks": BLOCKS,
        "counts": counts,
        "total": len(controls),
        "rc_zero": payload.get("rc_zero") is True,
        "label_width": label_width,
    }
    return json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")

def write_handoff(raw):
    view = memoryview(raw)
    while view:
        written = os.write(3, view)
        view = view[written:]

# --skip: control id или имя из колонки control (решение пользователя 07.10.2026).
_BY_NAME = {c["display_control"]: c["control_id"] for c in APPLY_CONTROLS}
_IDS = {c["control_id"] for c in APPLY_CONTROLS}
unknown = [item for item in SKIP_IDS if item not in _IDS and item not in _BY_NAME]
SKIP_IDS = [item if item in _IDS else _BY_NAME.get(item, item) for item in SKIP_IDS]
if unknown or len(set(SKIP_IDS)) != len(SKIP_IDS):
    print("REFUSED operator:skip-invalid: " + ",".join(unknown or SKIP_IDS), file=sys.stderr)
    raise SystemExit(2)
CONTAINERS = None
if CONTAINERS_TEXT:
    if (not (CONTAINERS_TEXT.isascii() and CONTAINERS_TEXT.isdigit()) or CONTAINERS_TEXT.startswith("0")
            or len(CONTAINERS_TEXT) > 10 or int(CONTAINERS_TEXT) > CONTAINERS_MAX
            or CONTAINERS_CONTROL not in _IDS):
        print("REFUSED operator:containers-invalid", file=sys.stderr)
        raise SystemExit(2)
    CONTAINERS = int(CONTAINERS_TEXT)
    for _c in APPLY_CONTROLS:
        if _c["control_id"] == CONTAINERS_CONTROL:
            _c["required"] = "= %d (--containers)" % CONTAINERS
started_at = now()
payload = {
    "schema": "SLP-APPLY-REPORT-V2",
    "dry_run": DRY_RUN,
    "apply_kinds": sorted({meta["apply_kind"] for meta in ROUTES.values()}),
    "apply_control_count": len(APPLY_CONTROLS),
    "started_at": started_at,
    "finished_at": None,
    "complete": False,
    "rc_zero": None,
    "run_error": None,
    "skip": list(SKIP_IDS),
    "containers": CONTAINERS,
    "system_type": SYSTEM_TYPE,
    "backup_dir": None,
    "controls": [],
}
try:
    ensure_state_dir()
except StateRefused as exc:
    print(f"REFUSED {exc.args[0]}: {exc.args[1]}", file=sys.stderr)
    raise SystemExit(1)
atomic_report(payload)
try:
    ensure_log_file(APPLY_LOG)
    ensure_log_file(DEBUG_LOG)
    append_log(APPLY_LOG, f"product apply start dry_run={str(DRY_RUN).lower()} controls={len(APPLY_CONTROLS)}")
    print(f"MODE={MODE} APPLY_CONTROLS={len(APPLY_CONTROLS)}")
    if not DRY_RUN:
        APPLY_STARTED_NS = __import__("time").time_ns()
        try:
            BACKUP_DIR = make_backup()
        except (OSError, RuntimeError) as exc:
            reason = str(exc) if str(exc).startswith("backup:") else "backup:failed"
            print("REFUSED " + reason, file=sys.stderr)
            payload["run_error"] = {"type": type(exc).__name__, "message": reason, "phase": "backup"}
            payload["finished_at"] = now()
            atomic_report(payload)
            append_log(APPLY_LOG, "product apply refused " + reason)
            raise SystemExit(1)
        payload["backup_dir"] = BACKUP_DIR
        atomic_report(payload)
        append_log(APPLY_LOG, "backup " + BACKUP_DIR)
        print("BACKUP=" + BACKUP_DIR)
        install_backup_hooks()
    _emit_separator()
    _emit_table_row("st", "source", "control", "current", "required")
    _emit_separator()
    loaded = {}
    # Сначала контроли механизмов, которые ставят пакеты; строки выводятся в порядке показа.
    execution = ([c for c in APPLY_CONTROLS if ROUTES.get(c["parameter_kind"], {}).get("installs_packages")]
                 + [c for c in APPLY_CONTROLS if not ROUTES.get(c["parameter_kind"], {}).get("installs_packages")])
    position = {c["control_id"]: i for i, c in enumerate(APPLY_CONTROLS)}
    records = {}
    shown = 0
    for control in execution:
        c_started = now()
        meta = ROUTES.get(control["parameter_kind"])
        if meta is None:
            record = unavailable_record(control, c_started, now())
        else:
            try:
                ns = loaded.get(control["parameter_kind"])
                if ns is None:
                    ns = load_route(meta)
                    loaded[control["parameter_kind"]] = ns
                append_log(APPLY_LOG, f"control start {control['control_id']} mechanism={meta['mechanism_id']}")
                skip = control["control_id"] in SKIP_IDS
                containers = CONTAINERS is not None and control["control_id"] == CONTAINERS_CONTROL
                desktop = (SYSTEM_TYPE == "DESKTOP" and control["control_id"] in DESKTOP_ADMIN
                           and not containers)
                # --skip и блок TYPE=DESKTOP: механизм только наблюдает (dry-run), без изменений.
                # --containers N: 2.5.5 получает значение N вместо значения контроля.
                result = ns["execute_control"](
                    control["control_id"], control["key"], control["op"],
                    CONTAINERS if containers else control["expected"], True,
                    dry_run=DRY_RUN or skip or desktop,
                )
                # Вывод внешних команд механизма (например, augenrules --load) — в apply.log
                # (решение пользователя 07.10.2026).
                log_lines = result.get("log_lines") if isinstance(result, dict) else None
                for line in log_lines if isinstance(log_lines, list) else []:
                    text = str(line).replace("\r", " ").replace("\n", " ")
                    append_log(APPLY_LOG, f"control log {control['control_id']} {text}")
                c_finished = now()
                raw = ns["control_result_to_report"](result, c_started, c_finished)
                mechanism_result = {k: v for k, v in raw.items() if k not in COMMON}
                if skip:
                    record = operator_record(raw, meta, "SKIPPED_BY_OPERATOR", "operator:skip")
                elif desktop and raw["outcome"] == "DRY_RUN_WOULD_APPLY":
                    record = operator_record(
                        raw, meta, "ABORTED_PRECONDITION_CONFLICT", "desktop:admin-decision",
                        {"class": "ADMIN_ACTION_REQUIRED", "required": True,
                         "action": DESKTOP_ADMIN[control["control_id"]]})
                else:
                    record = {
                        "control_id": raw["control_id"],
                        "mechanism_id": meta["mechanism_id"],
                        "outcome": raw["outcome"],
                        "reason": raw["reason"],
                        "actions_attempted": raw["actions_attempted"],
                        "step_rc": raw["step_rc"],
                        "mutation_performed": raw["mutation_performed"],
                        "transaction_commit": raw["transaction_commit"],
                        "started_at": raw["started_at"],
                        "finished_at": raw["finished_at"],
                        "mechanism_result": mechanism_result,
                    }
            except BaseException as exc:
                c_finished = now()
                append_log(DEBUG_LOG, traceback.format_exc().rstrip())
                record = crash_record(control, meta, c_started, c_finished, exc)
        payload["controls"].append(record)
        atomic_report(payload)
        records[control["control_id"]] = record
        while shown < len(APPLY_CONTROLS) and APPLY_CONTROLS[shown]["control_id"] in records:
            emit_control_result(records[APPLY_CONTROLS[shown]["control_id"]], APPLY_CONTROLS[shown])
            shown += 1
        append_log(APPLY_LOG, f"control finish {control['control_id']} outcome={record['outcome']} step_rc={record['step_rc']}")
    payload["controls"].sort(key=lambda item: position[item["control_id"]])
    payload["finished_at"] = now()
    payload["complete"] = True
    payload["rc_zero"] = all(item["step_rc"] == "0" for item in payload["controls"])
    atomic_report(payload)
    append_log(APPLY_LOG, f"product apply finish rc_zero={str(payload['rc_zero']).lower()}")
    _emit_separator()
    handoff = apply_handoff(payload)
    try:
        write_handoff(handoff)
    except OSError:
        print("APPLY_HANDOFF_UNAVAILABLE", file=sys.stderr)
        raise SystemExit(1)
    raise SystemExit(0 if payload["rc_zero"] else 1)
except SystemExit:
    raise
except BaseException as exc:
    payload["run_error"] = {"type": type(exc).__name__, "message": str(exc), "phase": "product-dispatch"}
    payload["finished_at"] = now()
    payload["complete"] = False
    payload["rc_zero"] = False
    try:
        atomic_report(payload)
        append_log(DEBUG_LOG, traceback.format_exc().rstrip())
    except Exception:
        pass
    raise

SLP_PRODUCT_APPLY_EOF
}

slp_run_apply() {
  # Итог dispatcher (дескриптор 3) — блоки и счётчики APPLY; после него CHECK контролей без APPLY,
  # затем таблица блоков, строки check и итоговая строка. Код возврата — APPLY.
  local _slp_mode=$1 _slp_skip=${2:-} _slp_handoff='' _slp_rc=0
  slp_target_preflight || return $?
  if [[ $_slp_mode == APPLY && $SLP_SYSTEM_TYPE == DESKTOP ]]; then
    {
      printf '\n%s\n' '+------------------------------------------------------------------------------------------+'
      printf '%s\n' '| ВНИМАНИЕ: UBUNTU DESKTOP = FIELD_COMPATIBILITY                                           |'
      printf '%s\n' '| Корректность APPLY на изменённой пользователем desktop-системе не гарантируется.         |'
      printf '%s\n' '| Установленные пакеты, службы и локальные настройки могут изменить поведение CHECK/APPLY. |'
      printf '%s\n' '| Перед APPLY выполните --apply --dry-run и обеспечьте внешний snapshot/backup.            |'
      printf '%s\n\n' '+------------------------------------------------------------------------------------------+'
    } >&2
  fi
  { _slp_handoff=$(slp_apply_dispatch "$_slp_mode" "$_slp_skip" 3>&1 1>&4 4>&-); _slp_rc=$?; } 4>&1
  [[ -n $_slp_handoff ]] || return "$_slp_rc"
  slp_collect_policy --record-errors 'FSTEC-LINUX-2022-2.1.1-LOCAL-ACCOUNT-PASSWORD-STATE' 'FSTEC-LINUX-2022-2.1.2-SSH-ROOT-LOGIN' 'FSTEC-LINUX-2022-2.2.1-SU-WHEEL-ACCESS' 'FSTEC-LINUX-2022-2.2.2-SUDOERS-REVIEWED-POLICY' 'FSTEC-LINUX-2022-2.3.1-GROUP-MODE' 'FSTEC-LINUX-2022-2.3.1-PASSWD-MODE' 'FSTEC-LINUX-2022-2.3.1-SHADOW-GO-RWX' 'FSTEC-LINUX-2022-2.3.2-RUNNING-PROCESS-PATHS-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.3-CRON-COMMAND-PATHS-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.4-SUDO-ROOT-COMMAND-FILES-PROTECTION' 'FSTEC-LINUX-2022-2.3.5-STARTUP-FILES-WRITE-PROTECTION' 'FSTEC-LINUX-2022-2.3.6-CRON-D' 'FSTEC-LINUX-2022-2.3.6-CRON-DAILY' 'FSTEC-LINUX-2022-2.3.6-CRON-HOURLY' 'FSTEC-LINUX-2022-2.3.6-CRON-MONTHLY' 'FSTEC-LINUX-2022-2.3.6-CRON-WEEKLY' 'FSTEC-LINUX-2022-2.3.6-CRONTAB' 'FSTEC-LINUX-2022-2.3.7-USER-CRON-FILES-MODE' 'FSTEC-LINUX-2022-2.3.8-STANDARD-SYSTEM-PATHS-MODE' 'FSTEC-LINUX-2022-2.3.9-SUID-SGID-MODE' 'FSTEC-LINUX-2022-2.3.10-HOME-SENSITIVE-FILES-MODE' 'FSTEC-LINUX-2022-2.3.11-DIR-MODE' 'FSTEC-LINUX-2022-2.3.11-HOME-DIRECTORIES-MODE' 'FSTEC-LINUX-2022-2.3.11-HOME-MODE' 'FSTEC-LINUX-2022-2.4.1-DMESG-RESTRICT' 'FSTEC-LINUX-2022-2.4.2-KPTR-RESTRICT' 'FSTEC-LINUX-2022-2.4.3-INIT-ON-ALLOC' 'FSTEC-LINUX-2022-2.4.4-SLAB-NOMERGE' 'FSTEC-LINUX-2022-2.4.5-IOMMU-FORCE' 'FSTEC-LINUX-2022-2.4.5-IOMMU-PASSTHROUGH' 'FSTEC-LINUX-2022-2.4.5-IOMMU-STRICT' 'FSTEC-LINUX-2022-2.4.6-RANDOMIZE-KSTACK-OFFSET' 'FSTEC-LINUX-2022-2.4.7-MITIGATIONS' 'FSTEC-LINUX-2022-2.4.8-BPF-JIT-HARDEN' 'FSTEC-LINUX-2022-2.5.1-VSYSCALL' 'FSTEC-LINUX-2022-2.5.2-PERF-EVENT-PARANOID' 'FSTEC-LINUX-2022-2.5.3-DEBUGFS' 'FSTEC-LINUX-2022-2.5.4-KEXEC-LOAD-DISABLED' 'FSTEC-LINUX-2022-2.5.5-MAX-USER-NAMESPACES' 'FSTEC-LINUX-2022-2.5.6-UNPRIVILEGED-BPF-DISABLED' 'FSTEC-LINUX-2022-2.5.7-UNPRIVILEGED-USERFAULTFD' 'FSTEC-LINUX-2022-2.5.8-LDISC-AUTOLOAD' 'FSTEC-LINUX-2022-2.5.9-TSX' 'FSTEC-LINUX-2022-2.5.10-MMAP-MIN-ADDR' 'FSTEC-LINUX-2022-2.5.11-RANDOMIZE-VA-SPACE' 'FSTEC-LINUX-2022-2.6.1-PTRACE-SCOPE' 'FSTEC-LI