ALL_IDS = json.loads(r'["FSTEC-CONFIGURATION-2026-1.1-ENCRYPT-METHOD","FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGE","FSTEC-CONFIGURATION-2026-1.1-EXISTING-PASSWORD-AGING","FSTEC-CONFIGURATION-2026-1.1-PASS-MAX-DAYS","FSTEC-CONFIGURATION-2026-1.1-PASS-MIN-DAYS","FSTEC-CONFIGURATION-2026-1.1-PASS-WARN-AGE","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-DCREDIT","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-ENFORCE-FOR-ROOT","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-LCREDIT","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-MINLEN","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-OCREDIT","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-RETRY","FSTEC-CONFIGURATION-2026-1.1-PWQUALITY-UCREDIT","FSTEC-CONFIGURATION-2026-1.2-PWHISTORY-ENFORCE-FOR-ROOT","FSTEC-CONFIGURATION-2026-1.2-PWHISTORY-REMEMBER","FSTEC-CONFIGURATION-2026-11.2-FTP","FSTEC-CONFIGURATION-2026-11.2-SNMP","FSTEC-CONFIGURATION-2026-11.2-TELNET","FSTEC-CONFIGURATION-2026-8.4-SSH-LOG-LEVEL","FSTEC-CONFIGURATION-2026-9.1-SSH-PASSWORD-AUTHENTICATION","FSTEC-CONFIGURATION-2026-9.1-SSH-PERMIT-EMPTY-PASSWORDS","FSTEC-CONFIGURATION-2026-9.1-SSH-PERMIT-ROOT-LOGIN","FSTEC-LINUX-2022-2.1.1-LOCAL-ACCOUNT-PASSWORD-STATE","FSTEC-LINUX-2022-2.1.2-SSH-ROOT-LOGIN","FSTEC-LINUX-2022-2.2.1-SU-WHEEL-ACCESS","FSTEC-LINUX-2022-2.2.2-SUDOERS-REVIEWED-POLICY","FSTEC-LINUX-2022-2.3.1-GROUP-MODE","FSTEC-LINUX-2022-2.3.1-PASSWD-MODE","FSTEC-LINUX-2022-2.3.1-SHADOW-GO-RWX","FSTEC-LINUX-2022-2.3.10-HOME-SENSITIVE-FILES-MODE","FSTEC-LINUX-2022-2.3.11-DIR-MODE","FSTEC-LINUX-2022-2.3.11-HOME-DIRECTORIES-MODE","FSTEC-LINUX-2022-2.3.11-HOME-MODE","FSTEC-LINUX-2022-2.3.2-RUNNING-PROCESS-PATHS-WRITE-PROTECTION","FSTEC-LINUX-2022-2.3.3-CRON-COMMAND-PATHS-WRITE-PROTECTION","FSTEC-LINUX-2022-2.3.4-SUDO-ROOT-COMMAND-FILES-PROTECTION","FSTEC-LINUX-2022-2.3.5-STARTUP-FILES-WRITE-PROTECTION","FSTEC-LINUX-2022-2.3.6-CRON-D","FSTEC-LINUX-2022-2.3.6-CRON-DAILY","FSTEC-LINUX-2022-2.3.6-CRON-HOURLY","FSTEC-LINUX-2022-2.3.6-CRON-MONTHLY","FSTEC-LINUX-2022-2.3.6-CRON-WEEKLY","FSTEC-LINUX-2022-2.3.6-CRONTAB","FSTEC-LINUX-2022-2.3.7-USER-CRON-FILES-MODE","FSTEC-LINUX-2022-2.3.8-STANDARD-SYSTEM-PATHS-MODE","FSTEC-LINUX-2022-2.3.9-SUID-SGID-MODE","FSTEC-LINUX-2022-2.4.1-DMESG-RESTRICT","FSTEC-LINUX-2022-2.4.2-KPTR-RESTRICT","FSTEC-LINUX-2022-2.4.3-INIT-ON-ALLOC","FSTEC-LINUX-2022-2.4.4-SLAB-NOMERGE","FSTEC-LINUX-2022-2.4.5-IOMMU-FORCE","FSTEC-LINUX-2022-2.4.5-IOMMU-PASSTHROUGH","FSTEC-LINUX-2022-2.4.5-IOMMU-STRICT","FSTEC-LINUX-2022-2.4.6-RANDOMIZE-KSTACK-OFFSET","FSTEC-LINUX-2022-2.4.7-MITIGATIONS","FSTEC-LINUX-2022-2.4.8-BPF-JIT-HARDEN","FSTEC-LINUX-2022-2.5.1-VSYSCALL","FSTEC-LINUX-2022-2.5.10-MMAP-MIN-ADDR","FSTEC-LINUX-2022-2.5.11-RANDOMIZE-VA-SPACE","FSTEC-LINUX-2022-2.5.2-PERF-EVENT-PARANOID","FSTEC-LINUX-2022-2.5.3-DEBUGFS","FSTEC-LINUX-2022-2.5.4-KEXEC-LOAD-DISABLED","FSTEC-LINUX-2022-2.5.5-MAX-USER-NAMESPACES","FSTEC-LINUX-2022-2.5.6-UNPRIVILEGED-BPF-DISABLED","FSTEC-LINUX-2022-2.5.7-UNPRIVILEGED-USERFAULTFD","FSTEC-LINUX-2022-2.5.8-LDISC-AUTOLOAD","FSTEC-LINUX-2022-2.5.9-TSX","FSTEC-LINUX-2022-2.6.1-PTRACE-SCOPE","FSTEC-LINUX-2022-2.6.2-PROTECTED-SYMLINKS","FSTEC-LINUX-2022-2.6.3-PROTECTED-HARDLINKS","FSTEC-LINUX-2022-2.6.4-PROTECTED-FIFOS","FSTEC-LINUX-2022-2.6.5-PROTECTED-REGULAR","FSTEC-LINUX-2022-2.6.6-SUID-DUMPABLE","FSTEC-LOGGING-2025-APPENDIX2-LINUX-1-AUDITD-PACKAGE","FSTEC-LOGGING-2025-APPENDIX2-LINUX-2-AUDITD-SERVICE","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-ADMIN-SPACE-LEFT-ACTION","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-DISK-FULL-ACTION","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FILE","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-FORMAT","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-LOG-GROUP","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-MAX-LOG-FILE-ACTION","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-NUM-LOGS","FSTEC-LOGGING-2025-APPENDIX2-LINUX-3-SPACE-LEFT-ACTION","FSTEC-LOGGING-2025-APPENDIX2-LINUX-4-AUDIT-RULES","FSTEC-LOGGING-2025-MAIN-5-AUDIT-LOG-FREE-SPACE"]')
STATUS_ORDER = ("PASS", "FAIL", "NOT_FOUND", "NOT_APPLICABLE", "ERROR")
SHOWN = ("FAIL", "ERROR", "NOT_FOUND")
ERROR_CURRENT_PREFIX = "not-determined; reason: "
# Допустимые пары наблюдения и результата — как в slp_collect_policy.
PAIRS = {("VALUE", "PASS"), ("VALUE", "FAIL"), ("NOT_FOUND", "FAIL"), ("NOT_FOUND", "NOT_FOUND"),
         ("NOT_APPLICABLE", "NOT_APPLICABLE"), ("ERROR", "ERROR")}
HANDOFF_FIELDS = {"schema", "blocks", "counts", "total", "rc_zero", "label_width"}

def _terminal_scalar(value, label):
    if value is None or isinstance(value, (dict, list, tuple, set)):
        raise RuntimeError("presentation:" + label + "-invalid")
    text = str(value)
    if not text or "\n" in text or "\r" in text:
        raise RuntimeError("presentation:" + label + "-invalid")
    return text

def _table_chunks(value, width, label):
    text = _terminal_scalar(value, label) if value != "" else ""
    if not text:
        return [""]
    return [text[i:i + width] for i in range(0, len(text), width)]

def _word_chunks(value, width, label):
    # Перенос по пробелам; слово длиннее колонки режется по ширине.
    text = _terminal_scalar(value, label) if value != "" else ""
    chunks, line = [], ""
    for word in text.split(" "):
        while len(word) > width:
            if line:
                chunks.append(line)
                line = ""
            chunks.append(word[:width])
            word = word[width:]
        if not word:
            continue
        if line and len(line) + 1 + len(word) > width:
            chunks.append(line)
            line = word
        else:
            line = line + " " + word if line else word
    chunks.append(line)
    return chunks

def _terminal_columns():
    try:
        cols = os.get_terminal_size(sys.stdout.fileno()).columns
    except (OSError, ValueError):
        return 116
    if not isinstance(cols, int) or cols < 40 or cols > 1000:
        return 116
    return cols


PRETTY_COLUMNS = _terminal_columns()
PRETTY_IS_TTY = sys.stdout.isatty()


def _order_valid(order):
    # Ключ порядка строк: [год, doc_id, [[0, число] | [1, текст], ...], control_id].
    return (isinstance(order, list) and len(order) == 4 and type(order[0]) is int
            and isinstance(order[1], str) and isinstance(order[3], str) and isinstance(order[2], list)
            and all(isinstance(t, list) and len(t) == 2 and ((t[0] == 0 and type(t[1]) is int)
                    or (t[0] == 1 and isinstance(t[1], str))) for t in order[2]))


def load_handoff(raw):
    data = json.loads(raw)
    if not isinstance(data, dict) or set(data) != HANDOFF_FIELDS or data["schema"] != "SLP-APPLY-HANDOFF-V1":
        raise RuntimeError("summary:handoff-invalid")
    if (not isinstance(data["blocks"], list) or not isinstance(data["counts"], dict)
            or not isinstance(data["rc_zero"], bool) or type(data["total"]) is not int
            or type(data["label_width"]) is not int):
        raise RuntimeError("summary:handoff-invalid")
    for name, count in data["counts"].items():
        _terminal_scalar(name, "outcome")
        if type(count) is not int or count < 1:
            raise RuntimeError("summary:handoff-invalid")
    if sum(data["counts"].values()) != data["total"]:
        raise RuntimeError("summary:handoff-invalid")
    for entry in data["blocks"]:
        if (not isinstance(entry, dict) or set(entry) != {"control", "rows", "admin", "risk", "order"}
                or not isinstance(entry["rows"], list) or not entry["rows"]
                or not isinstance(entry["admin"], bool) or not _order_valid(entry["order"])):
            raise RuntimeError("summary:handoff-invalid")
        _terminal_scalar(entry["control"], "block-control")
        if entry["risk"] is not None:
            _terminal_scalar(entry["risk"], "risk")
        for row in entry["rows"]:
            if not isinstance(row, list) or len(row) != 2:
                raise RuntimeError("summary:handoff-invalid")
            _terminal_scalar(row[0], "block-type")
            _terminal_scalar(row[1], "block-message")
    return data


def load_checks(lines):
    results = []
    for line in lines:
        fields = line.split("\t")
        if len(fields) != 5 or fields[0] != "SLP-CHECK-V1":
            raise RuntimeError("summary:check-line-invalid")
        _tag, cid, status, value, comp = fields
        if cid not in ALL_IDS or any(cid == item[0] for item in results):
            raise RuntimeError("summary:check-id-invalid")
        if (status, comp) not in PAIRS:
            raise RuntimeError("summary:check-status-invalid")
        if status == "VALUE":
            current = value
        elif status == "NOT_FOUND":
            current = "<absent>"
        elif status == "NOT_APPLICABLE":
            current = "<not-applicable>"
        elif status == "ERROR":
            current = ERROR_CURRENT_PREFIX + value
        else:
            raise RuntimeError("summary:check-status-invalid")
        results.append((cid, comp, current))
    if {cid for cid, _comp, _current in results} != set(ALL_IDS):
        raise RuntimeError("summary:check-set-invalid")
    return results


def layout(need):
    cols = PRETTY_COLUMNS if PRETTY_IS_TTY else 116
    wtype = 6
    wcontrol = min(max(12, need), max(12, cols // 3))
    wmessage = cols - 9 - wcontrol - wtype
    if wmessage < 12:
        raise RuntimeError("presentation:blocks-terminal-width-invalid")
    return wcontrol, wtype, wmessage


def emit_row(widths, control, kind, message):
    wcontrol, wtype, wmessage = widths
    control_chunks = _table_chunks(control, wcontrol, "block-control")
    kind_chunks = _table_chunks(kind, wtype, "block-type")
    message_chunks = _word_chunks(message, wmessage, "block-message")
    rows = max(len(control_chunks), len(kind_chunks), len(message_chunks))
    for i in range(rows):
        c = control_chunks[i] if i < len(control_chunks) else ""
        k = kind_chunks[i] if i < len(kind_chunks) else ""
        m = message_chunks[i] if i < len(message_chunks) else ""
        print(f" {c:<{wcontrol}} | {k:<{wtype}} | {m:<{wmessage}} |")


def emit_separator(widths):
    wcontrol, wtype, wmessage = widths
    print("-" * (wcontrol + 2) + "+" + "-" * (wtype + 2) + "+" + "-" * (wmessage + 2) + "+")


def emit_tables(blocks, results, need):
    shown = [(cid, comp, current) for cid, comp, current in results if comp in SHOWN]
    if not blocks and not shown:
        return
    widths = layout(need)
    if blocks:
        # Первая строка определяет статус block основной таблицы и общие для блоков фразы
        # (решения пользователя 24.09.2026). «Не применено» верно для каждого блока: _block_entry
        # требует mutation_performed=False.
        all_admin = all(entry["admin"] for entry in blocks)
        print("block — не применено автоматически"
              + (", требуется решение администратора" if all_admin else "") + f" ({len(blocks)}):")
        if any(kind == "add" for entry in blocks for kind, _message in entry["rows"]):
            print("add: добавить параметр в GRUB_CMDLINE_LINUX, выполнить update-grub и перезагрузить систему.")
    else:
        all_admin = False
    if shown:
        print(f"check — результат CHECK после APPLY, FAIL, NOT_FOUND или ERROR ({len(shown)}):")
    emit_separator(widths)
    emit_row(widths, "control", "type", "message")
    emit_separator(widths)
    # Строки block и check — одной последовательностью в порядке CHECK (решение пользователя
    # 07.10.2026); ключ порядка — presentation_key генератора.
    items = [(entry["order"], "block", entry) for entry in blocks]
    items += [(META[cid]["order"], "check", (cid, comp, current)) for cid, comp, current in shown]
    items.sort(key=lambda item: item[0])
    for i, (_order, kind_of, item) in enumerate(items):
        if kind_of == "check":
            cid, comp, current = item
            emit_row(widths, META[cid]["label"], "check", comp + ": " + current)
            note = META[cid]["reason"]
            # Причина — весь остаток после префикса, с которым load_checks строит значение ERROR
            if comp == "ERROR" and current.startswith(ERROR_CURRENT_PREFIX):
                note = META[cid]["error_notes"].get(current[len(ERROR_CURRENT_PREFIX):], note)
            emit_row(widths, "", "note", note)
            continue
        entry = item
        for n, (kind, message) in enumerate(entry["rows"]):
            emit_row(widths, entry["control"] if n == 0 else "", kind, message)
        if entry["admin"] and not all_admin:
            emit_row(widths, "", "note", "Требуется решение администратора.")
        # Одинаковый риск у блоков подряд — один раз, после последнего из них.
        following = next((item[2] for item in items[i + 1:] if item[1] == "block"), None)
        if entry["risk"] and (following is None or following["risk"] != entry["risk"]):
            emit_row(widths, "", "risk", entry["risk"])
    emit_separator(widths)


def summary_line(data, results, checks):
    parts = " ".join(f"{name}={data['counts'][name]}" for name in sorted(data["counts"]))
    check_counts = {}
    for _cid, comp, _current in checks:
        check_counts[comp] = check_counts.get(comp, 0) + 1
    check_parts = " ".join(f"{name}={check_counts[name]}" for name in STATUS_ORDER if name in check_counts)
    totals = {name: 0 for name in STATUS_ORDER}
    for _cid, comp, _current in results:
        totals[comp] += 1
    total_parts = " ".join(f"{name}={totals[name]}" for name in STATUS_ORDER)
    return (f"APPLY={data['total']}" + (f" ({parts})" if parts else "")
            + f"\nCHECK_ONLY={len(checks)}" + (f" ({check_parts})" if check_parts else "")
            + f"\nTOTAL={len(results)} {total_parts} RC={'0' if data['rc_zero'] else 'NONZERO'}")


def main():
    if len(sys.argv) < 2:
        raise RuntimeError("summary:arguments-invalid")
    data = load_handoff(sys.argv[1])
    results = load_checks(sys.argv[2:])
    checks = [item for item in results if not META[item[0]]["apply"]]
    if len(results) != data["total"] + len(checks):
        raise RuntimeError("summary:total-invalid")
    need = max([data["label_width"]] + [len(META[cid]["label"]) for cid in META if not META[cid]["apply"]])
    emit_tables(data["blocks"], results, need)
    print(summary_line(data, results, checks))


try:
    main()
except Exception:
    print("APPLY_SUMMARY_INTERNAL_ERROR", file=sys.stderr)
    raise SystemExit(1)

SLP_PRODUCT_APPLY_SUMMARY_EOF
  return "$_slp_rc"
}

# --containers N: целое 1..2147483647 без ведущих нулей (решение пользователя 08.10.2026).
slp_containers_valid() {
  [[ $1 =~ ^[1-9][0-9]{0,9}$ ]] || return 1
  (( 10#$1 <= 2147483647 ))
}

slp_main() {
  local _slp_format=pretty _slp_failed_only=0 _slp_apply_mode=APPLY _slp_skip='' _slp_item='' _slp_containers=''
  if (( $# == 0 )); then
    slp_help
    return 0
  fi
  case "$1" in
    --help)
      (( $# == 1 )) || return 2
      slp_help
      return 0
      ;;
    --version)
      (( $# == 1 )) || return 2
      slp_version
      return 0
      ;;
    --build-info)
      (( $# == 1 )) || return 2
      slp_build_info
      return 0
      ;;
    --list)
      (( $# == 1 )) || return 2
      slp_list
      return 0
      ;;
    --provenance)
      if (( $# == 1 )); then
        slp_provenance_all
      elif (( $# == 2 )); then
        slp_provenance_one "$2" || return 2
      else
        return 2
      fi
      return 0
      ;;
    --apply)
      shift
      # --skip — решение пользователя 07.10.2026: список control id через запятую, ключ повторяем.
      while (( $# > 0 )); do
        case "$1" in
          --dry-run)
            [[ $_slp_apply_mode == APPLY ]] || return 2
            _slp_apply_mode=DRY_RUN
            ;;
          --skip|--skip=*)
            if [[ $1 == --skip ]]; then
              shift
              (( $# > 0 )) || return 2
              _slp_item=$1
            else
              _slp_item=${1#--skip=}
            fi
            [[ $_slp_item =~ ^[A-Za-z0-9._-]+(,[A-Za-z0-9._-]+)*$ ]] || return 2
            _slp_skip=${_slp_skip:+$_slp_skip,}$_slp_item
            ;;
          --containers|--containers=*)
            [[ -z $_slp_containers ]] || return 2
            if [[ $1 == --containers ]]; then
              shift
              (( $# > 0 )) || return 2
              _slp_containers=$1
            else
              _slp_containers=${1#--containers=}
            fi
            slp_containers_valid "$_slp_containers" || return 2
            ;;
          *) return 2 ;;
        esac
        shift
      done
      SLP_CONTAINERS=$_slp_containers
      slp_run_apply "$_slp_apply_mode" "$_slp_skip"
      return $?
      ;;
    --report)
      (( $# == 1 )) || return 2
      slp_run_check pretty 1 REPORT
      return $?
      ;;
    --check)
      shift
      while (( $# > 0 )); do
        case "$1" in
          --failed)
            (( _slp_failed_only == 0 )) || return 2
            _slp_failed_only=1
            ;;
          --format)
            shift
            (( $# > 0 )) || return 2
            case "$1" in pretty|raw|json) _slp_format=$1 ;; *) return 2 ;; esac
            ;;
          --format=*)
            _slp_format=${1#--format=}
            case "$_slp_format" in pretty|raw|json) ;; *) return 2 ;; esac
            ;;
          *) return 2 ;;
        esac
        shift
      done
      slp_run_check "$_slp_format" "$_slp_failed_only" CHECK
      return $?
      ;;
    *)
      return 2
      ;;
  esac
}

if [[ ${BASH_SOURCE[0]} == "$0" ]]; then
  slp_main "$@"
  exit $?
fi
